import Foundation

private typealias E = EvidenceSeed

/// One new follow-up trial for each of the batch BL stories: the same defendant, back in this court.
extension FollowUpCases {
    static let batchBL: [CaseTemplate] = [sharedApartmentBack, fishingCabinBack, payrollRobberyBack, carjackingRobberyBack, pickupLineSpeedingBack, altereCheckMailBack, rentalCarPillsBack, parkingLotSleeperBack, roadBlockadeBack, restraintDeathBack, exHouseKeyBack, truckStopKillerBack, taserMistakeBack, paradeSUVBack, parentsMansionBack, trailMurdersBack, dogMaulingBack, cityStranglerBack, hazingDeathBack, hurricaneFraudBack, fakeDoctorBack, daycareCamerasBack, feedStoreFireBack, tractorDWIBack]

    static let sharedApartmentBack = SmallCases.make(
        key: "story.followup.sharedApartmentBack",
        category: .drugs,
        headlines: ["Pills Found in Warehouse Locker After Tip", "Former Apartment Defendant Faces New Drug Charge"],
        law: "possSchedII",
        spec: "Knowingly possessed oxycodone pills, a Schedule II controlled substance, on {DATE}.",
        ages: 21...40,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a manager opened {D}'s locker at a distribution warehouse after a coworker complained and found a bottle with 14 oxycodone pills and no label. {DL} says the locker had been used by a temp worker before and the bottle was never {D.his}.",
        state: [E(.physical, 3, "Locker and Bottle", "An unlabeled bottle with 14 oxycodone pills inside {DL}'s assigned locker."), E(.forensic, 2, "Lab Report", "The lab confirms the pills are oxycodone.")],
        defense: [E(.document, 1, "Locker Log", "The locker list shows a temp worker used it before {DL}.")],
        role: "Warehouse manager",
        exam: [.direct("What is your position at the distribution warehouse?", "\"I am the warehouse manager. I supervise about sixty workers on three shifts, and I am responsible for safety, the lockers, and anything that is reported to me.\""),
               .direct("What led you to open {DL}'s locker?", "\"A coworker came to me and said they were worried about what was in it. After that I was required to look, so I went with a second supervisor and opened it with the master key.\""),
               .direct("What did you find inside?", "\"A plastic bottle with no label on it, holding fourteen pills. I did not touch them, and I called the sheriff's office right away.\""),
               .direct("How do you know the pills are oxycodone?", "\"The lab report confirms it. A deputy took the bottle, and the lab tested the pills and found them to be oxycodone.\""),
               .direct("Who has access to those lockers?", "\"Only the worker who is assigned the locker has a combination, and I hold a master key. Nobody else is supposed to be in there.\""),
               .direct("Whose locker was it that day?", "\"It was assigned to {DL} about thirty days before. I have the locker list in my office, with the dates for each worker.\""),
               .direct("How did {DL} respond when you told {D.him}?", "\"{D.He} said the bottle was not {D.his}. {D.He} said a temp worker had used that locker before, and {D.he} had only kept lunch there.\""),
               .cross("Was the locker used by someone else before {DL}?", "\"Yes, a temp worker had it several months earlier. The log shows that worker's name and the dates.\""),
               .cross("Was the locker cleaned between users?", "\"It is supposed to be, but we have a lot of turnover. I cannot say it was emptied that day.\""),
               .cross("Did you ever see {DL} take anything out of that locker?", "\"No, I did not. I only know what I found when I opened it.\""),
               .cross("Does anyone besides {DL} have access with the master key?", "\"Me, and the second supervisor who was there when we opened it. That is all.\""),
               .cross("You do not know when that bottle was put in the locker, do you?", "\"No, I do not. I cannot tell the jury whether it was there for a day or for months.\"")],
        theory: ("Pills were found in {D}'s own assigned locker at a distribution warehouse.", "A bottle left behind by a former locker user, which {D} never knew about."),
        allocution: "\"That bottle was not mine. The locker had been used by a temp worker before me, and I only kept my lunch in it. I never knew there were pills inside. I'm sorry that a coworker was worried and that the manager had to open it. I'd ask the court to look at who had that locker before.\"",
        truths: ("{DL} had a prior case in this court over pills in a shared apartment, and a coworker saw {D.him} open the bottle at break.", "The temp worker who used the locker earlier was later fired for pill use, and {DL} had never opened the bottle."),
        defendant: [.direct("Are those your pills?", "\"No, they are not. I have never seen that bottle before the manager showed it to me.\""),
               .direct("What did you keep in that locker?", "\"My lunch, a jacket, and a pair of work gloves. That is all I ever put in it.\""),
               .direct("Who used the locker before you?", "\"A temp worker, according to the list. I was told the locker was empty when it was assigned to me, and I never looked inside the back corner.\""),
               .direct("Did you ever check the whole locker?", "\"Not carefully. I opened the door, put my things on the hook, and closed it. I did not look at the shelf up top.\""),
               .direct("Why would you not have hidden the bottle if it was yours?", "\"I would not have kept something like that where a manager could open it. If it had been mine, it would not have been in a locker I did not control.\""),
               .direct("What do you want the court to know?", "\"I am sorry a coworker was worried and that the manager had to open it. I would ask the court to look at who had that locker before me.\""),
               .cross("Your last case in this court was in {PRIORDATE}, wasn't it, over {PRIOR}?", "\"Yes, and I know that history makes people look at me first. That does not make the bottle mine.\""),
               .cross("A coworker said you were opening a bottle at break, didn't they?", "\"I have heard that, but I was opening a bottle of vitamins. I would never open a bottle like that in front of people.\""),
               .cross("You were assigned that locker about thirty days earlier, weren't you?", "\"Yes, that sounds right. I had been using it for lunch and a coat, and I never noticed the shelf above the hooks.\""),
               .cross("Only you had the combination, didn't you?", "\"Yes, and the manager has the master key. I do not know who else could have gotten in.\""),
               .cross("The temp worker was later fired for pill use, wasn't that worker?", "\"I have heard that, and it is one reason I think the bottle was left by that person.\"")],
        openings: ("A warehouse manager opened {D}'s locker after a coworker's complaint and found an unlabeled bottle with fourteen oxycodone pills inside. The locker was assigned to {DL}, who had a case in this court in {PRIORDATE} over {PRIOR}, and the lab confirms what the pills are.", "The defense will present a locker log showing that a temp worker used the locker months earlier, and a worker who kept only lunch in it. A bottle that may have been left behind is not possession by {D}."),
        closings: ("The locker was assigned to {DL}, only {DL} had the combination, and the pills were inside. A person who is responsible for a locker is responsible for what is in it, and {D} had been here before over pills.", "The log shows someone else used that locker first, a worker was fired later for pill use, and {D} never opened that shelf. The State has not shown that {D} knew the bottle was there."),
        timeline: [(-30, "{D} is assigned the locker, which a temp worker had used months earlier."), (0, "A coworker raises a concern and the manager opens the locker with a second supervisor."), (0, "The manager finds a bottle with fourteen unlabeled pills and calls the sheriff's office."), (1, "The lab confirms the pills are oxycodone and {D} is charged.")],
        identified: "A coworker's complaint.",
        mood: .indifferent)

    static let fishingCabinBack = SmallCases.make(
        key: "story.followup.fishingCabinBack",
        category: .publicOrder,
        headlines: ["Marina Dock Hand Says Boater Threatened to Drown Them", "Lake Cabin Defendant Faces Threat Charge"],
        law: "communicatingThreats",
        spec: "Willfully threatened {V} with physical injury by saying {V.he} would be dropped in the lake, on {DATE}.",
        ages: 38...68,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} argued with {V}, a marina dock hand, over a boat slip fee at a lake marina. {DL} told {V} loudly, 'I'll put you in the lake and nobody will look.' A fuel customer heard it. {DL} says it was a joke made in anger.",
        state: [E(.statement, 3, "Fuel Customer", "A customer heard {D} say 'I'll put you in the lake and nobody will look.'"), E(.video, 2, "Dock Camera", "{D} jabs a finger at {V} and shouts; no sound.")],
        defense: [E(.statement, 1, "Venting", "{DL} says it was a figure of speech.")],
        role: "Marina dock hand",
        exam: [.direct("What is your job at the marina?", "\"I work the docks at a lake marina. I tie up boats, pump fuel, collect slip fees, and help customers launch and haul out.\""),
               .direct("What was the argument about?", "\"{DL} had rented a slip for the month, and the fee was overdue. I asked politely for the payment, and {D.he} got angry.\""),
               .direct("What did {DL} say to you?", "\"{D.He} shouted that {D.he} would put me in the lake and nobody would look. {D.He} jabbed a finger toward my chest as {D.he} said it.\""),
               .direct("Who else heard it?", "\"A customer at the fuel dock, a few feet away, heard the whole thing. The customer came to me afterward and said they were worried for me.\""),
               .direct("How did you feel?", "\"Afraid. Everyone on the docks had heard stories about {DL}, and I thought about how deep the water is where the boats are tied up.\""),
               .direct("What does the dock camera show?", "\"It shows {DL} jabbing a finger at me and shouting. It has no sound, but you can see how close {D.he} was.\""),
               .direct("What did you do?", "\"I stepped back, finished fueling the boat I was working on, and told the marina owner. The owner called the sheriff's office.\""),
               .cross("Did {DL} touch you?", "\"No, {D.he} did not. {D.He} stayed about an arm's length away the whole time, and {D.he} never reached for me or grabbed anything.\""),
               .cross("Did {DL} say anything else?", "\"When {D.he} walked away, {D.he} said I mean it. I do not know whether {D.he} was still talking to me.\""),
               .cross("Did {DL} pay the fee afterward?", "\"I have been told {D.he} paid within the hour. I was not at the office when {D.he} did.\""),
               .cross("Did {DL} apologize?", "\"{D.He} came back and said something at the office, but I was not there.\""),
               .cross("You were not physically threatened, were you?", "\"Not physically, but the words were clear enough for me to believe it.\"")],
        theory: ("{D} threatened to put a dock hand in the lake after a fee argument.", "{D} said an angry thing over a slip fee and did not mean it."),
        allocution: "\"I said something stupid in the middle of an argument about a slip fee, and I did not mean it. I was angry, and the words came out wrong. I'm sorry that {V} and the customer at the fuel dock heard it. I'd never hurt anyone at that marina, and I'll pay what I owe.\"",
        truths: ("{DL} had a prior case in this court and said, 'I mean it,' as {D.he} walked away.", "{DL} paid the slip fee within the hour and apologized in person."),
        defendant: [.direct("Did you say that to the dock hand?", "\"I said something stupid in the middle of an argument. I know the words were wrong.\""),
               .direct("What was the argument about?", "\"A slip fee that I thought was too high. I had asked about it and nobody answered, so I was already angry.\""),
               .direct("Did you mean it?", "\"No. I never meant to hurt anyone. It was words that came out wrong when I was angry.\""),
               .direct("What happened after you said it?", "\"I walked away to my truck. I stopped for a moment and said I mean it, meaning that I was serious about the fee being wrong.\""),
               .direct("Did you pay the fee?", "\"Yes, within the hour. I walked to the office and paid the full amount.\""),
               .direct("Did you apologize?", "\"Yes, to the dock hand in person. I told {V.him} I did not mean it.\""),
               .cross("You told the dock hand you would put {V.him} in the lake, didn't you?", "\"I said something like that, and I know how it sounds. I was angry, and I did not think.\""),
               .cross("You said I mean it as you walked away, didn't you?", "\"Yes, I said that, and I meant it about the fee. I know it came across as a threat.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know that makes the words sound worse. I would never hurt anyone at that marina.\""),
               .cross("A customer at the fuel dock heard you, didn't they?", "\"Yes, I saw the customer standing there. I am sorry anyone else had to hear it, because it embarrassed me.\""),
               .cross("You jabbed a finger toward {V.him}, didn't you?", "\"Yes, I did, and that was wrong too. I was close and loud, and I should have walked away the moment I felt myself getting angry.\"")],
        openings: ("At a lake marina, {D} told {V}, a dock hand, 'I'll put you in the lake and nobody will look' during an argument over a slip fee. A fuel customer heard it, a camera shows {DL} jabbing a finger at {V}, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a boater who was angry over a bill and said something stupid in the heat of it. {D} paid the fee within the hour, apologized in person, and never touched anyone."),
        closings: ("A threat on the dock, heard by a fuel customer, with a finger jabbed at {V}'s chest and a parting I mean it. The State asks you to take {D} at {D.his} word.", "Words said in a bad moment over a slip fee, followed by an apology and full payment. The State has not shown that {D} meant to hurt anyone or that anyone was truly in danger."),
        timeline: [(0, "Morning: {D} argues with {V} over an overdue slip fee at the marina."), (0, "Noon: {D} says 'I'll put you in the lake and nobody will look' as a fuel customer stands nearby."), (0, "{D} pays the fee within the hour and apologizes in person."), (1, "The marina owner calls the sheriff's office and {D} is charged.")],
        identified: "A customer's report.",
        mood: .divided)

    static let payrollRobberyBack = SmallCases.make(
        key: "story.followup.payrollRobberyBack",
        category: .robbery,
        headlines: ["Car Wash Deposit Pouch Snatched From Attendant", "Poultry Plant Robbery Defendant Faces New Robbery Charge"],
        law: "commonLawRobbery",
        spec: "Took a bank deposit pouch containing $640 from the person and presence of {V} by violence or fear, on {DATE}.",
        ages: 20...43,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}, a car wash attendant, was carrying a deposit pouch with $640 to a drop box at dusk when a person in a gray hooded sweatshirt shoved {V.him} against a wall and ran with it. {V} scraped {V.his} hands. {D} was stopped two blocks away with a gray sweatshirt in a bag. {DL} says {D.he} was walking to a bus.",
        state: [E(.video, 3, "Drop Box Camera", "A hooded person shoves {V} and runs toward Pine Street."), E(.physical, 2, "Sweatshirt and Cash", "A gray sweatshirt in {DL}'s bag and $200 in the pocket.")],
        defense: [E(.document, 1, "Bus Pass", "A bus pass swiped three blocks away.")],
        role: "Car wash attendant",
        exam: [.direct("What is your job?", "\"I work as an attendant at a car wash. I wash cars, handle the register, and carry the day's deposit to the drop box at the end of my shift.\""),
               .direct("What happened that evening?", "\"At dusk I was walking to the drop box with a pouch holding $640. A person in a gray hooded sweatshirt came up from behind, shoved me against the wall, and grabbed the pouch.\""),
               .direct("What did the person do next?", "\"They ran down the street toward Pine Street. I fell and scraped both of my hands on the brick.\""),
               .direct("Did you see the face?", "\"No. The hood was pulled forward, and it was getting dark. I only saw a gray sweatshirt and a quick shape.\""),
               .direct("What does the drop box camera show?", "\"It shows a hooded person shoving me and running toward Pine Street. You can see the whole thing, but not the face.\""),
               .direct("What was found when {DL} was stopped?", "\"I have been told a gray sweatshirt in a bag and $200 in a pocket. I did not see it myself.\""),
               .direct("How has it affected you?", "\"I was scared for days, and I did not want to carry the pouch alone anymore. My boss pays for a ride now.\""),
               .cross("Could the hood have been any gray hooded sweatshirt?", "\"Yes, it could have been. Many people wear them, and it was cold that evening.\""),
               .cross("Did the person say anything?", "\"No, the person did not say a single word. It was only the shove and the sound of shoes running away down the block.\""),
               .cross("How much time passed before {DL} was stopped?", "\"A few minutes. {D.He} was stopped two blocks away, and I was told the police were already looking in that direction.\""),
               .cross("Was the sweatshirt in the bag the same one?", "\"It was gray, like the one in the video. I cannot say it was the same one.\""),
               .cross("You did not see the robber's face, did you?", "\"No, I did not, because the hood was pulled forward and it was nearly dark. I cannot honestly say that it was {DL}.\"")],
        theory: ("{D} shoved a car wash attendant and ran with a $640 deposit.", "{D} was walking to a bus in a gray sweatshirt and was stopped by mistake."),
        allocution: "\"I was at the bus stop wearing a gray sweatshirt because it was cold, and thousands of people own one like it. I'm sorry that {V} was shoved and scraped. I hope the person who took that pouch is found, and I'd ask the court to think about where I was.\"",
        truths: ("{DL} had a prior case in this court for taking a payroll bag and owed money again.", "The bus pass was swiped after the robbery and the cash was {DL}'s own wages."),
        defendant: [.direct("Did you take the pouch?", "\"No, I did not. I have never seen that pouch or that car wash.\""),
               .direct("Where were you going?", "\"To the bus stop, to go home from my job. I was walking down Pine Street toward it.\""),
               .direct("Why were you wearing a gray sweatshirt?", "\"It was cold, and it was the one I wear to work. Thousands of people own one like it.\""),
               .direct("What was in your bag?", "\"The sweatshirt I take to work, my lunch, and some of my wages in cash. I was paid in cash that day.\""),
               .direct("What about the bus pass?", "\"I used my bus pass at a stop three blocks from the car wash, after the robbery. The swipe shows the time.\""),
               .direct("What do you want the court to know?", "\"I did not rob anyone. I hope the person who did is found, and I am sorry for what happened to {V}.\""),
               .cross("You were stopped two blocks from the scene, weren't you?", "\"Yes, because I was walking toward the bus stop. I did not run, and I told the officer where I was going.\""),
               .cross("A gray sweatshirt was in your bag, wasn't it?", "\"Yes, the one I wear to work. It was in my bag because I took it off when I got warm.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know that history makes me look guilty. I did not do this.\""),
               .cross("$200 was in your pocket, wasn't it?", "\"Yes, my wages for the week. I was paid in cash and had not been to the bank.\""),
               .cross("Your bus pass was swiped after the robbery, wasn't it?", "\"Yes, a few minutes after, three blocks from the car wash. I was walking the whole way.\"")],
        openings: ("At dusk a person in a gray hooded sweatshirt shoved {V}, a car wash attendant, against a wall and ran with a $640 deposit. Two blocks away, {D} was stopped with a gray sweatshirt in a bag and $200 in a pocket, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a bus pass that was swiped minutes after the robbery, and a worker in a common gray sweatshirt who was walking to a bus. Looking like a robber is not being one."),
        closings: ("A shove on camera, a gray sweatshirt in {D}'s bag, and $200 in {D}'s pocket two blocks from where {V} fell and lost the deposit. The video and the sweatshirt point in one direction.", "A bus pass swiped three blocks away, wages in a pocket, and a gray sweatshirt that thousands of people own. The State has not shown that {D} was the person in that hood, and nobody saw a face."),
        timeline: [(0, "Dusk: a hooded person shoves {V} against a wall and takes the $640 pouch."), (0, "A few minutes later: {D} is stopped two blocks away with a gray sweatshirt in a bag."), (0, "A bus pass is swiped three blocks from the car wash."), (1, "{D} is charged with robbery.")],
        identified: "A deputy stopping {DL} two blocks away.",
        mood: .wantsConviction)

    static let carjackingRobberyBack = SmallCases.make(
        key: "story.followup.carjackingRobberyBack",
        category: .property,
        headlines: ["Wallet and Phone Taken From Locked Car at Gym", "Carjacking Defendant Faces Car Break-In Charge"],
        law: "breakingVehicle",
        spec: "Broke into the motor vehicle of {V} and took a wallet and a phone, on {DATE}.",
        ages: 18...48,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, while {V} was in a gym, a side window of {V.his} car was smashed and a wallet and phone were taken. A camera shows a person in a black cap at the car. {D} was found two days later using the phone. {DL} says {D.he} bought the phone online.",
        state: [E(.video, 3, "Lot Camera", "A person in a black cap reaches into the smashed window."), E(.digital, 2, "Phone Location", "The stolen phone connected to {DL}'s home network.")],
        defense: [E(.document, 1, "Online Receipt", "A receipt for a used phone for $90.")],
        role: "Gym member",
        exam: [.direct("What happened to your car?", "\"I parked in the gym lot and went in for a workout. When I came out, the side window was smashed, with glass on the seat.\""),
               .direct("What was taken?", "\"My wallet and my phone. I had left them on the passenger seat under a towel.\""),
               .direct("What does the lot camera show?", "\"A person in a black cap walks up to my car, reaches through the smashed window, and takes something. The face is not visible.\""),
               .direct("How did you learn about {DL}?", "\"A detective traced my phone. It connected to a home network that belongs to {DL}, two days later.\""),
               .direct("What did the loss cost you?", "\"A new window, a new license, and a new phone. It was about $900, plus the time at the DMV.\""),
               .direct("How has this changed your habits?", "\"I do not leave anything in my car anymore. I carry my wallet and phone into the gym with me.\""),
               .direct("Did you know {DL}?", "\"No, I had never heard the name until the detective called.\""),
               .cross("Did you see who smashed the window?", "\"No, I was inside the gym. I know only what the camera shows.\""),
               .cross("Could the person in the cap be anyone?", "\"Yes, the camera does not show a face. It shows only a cap.\""),
               .cross("Did the phone show up at {DL}'s home?", "\"The phone connected to {DL}'s network. I do not know how it got there.\""),
               .cross("Could {DL} have bought the phone from someone else?", "\"It is possible, and {D.he} says that is what happened. I have no way to know how the phone got from my car to {D.his} home.\""),
               .cross("You cannot say {DL} took it, can you?", "\"No, I cannot. I can say only that the phone was mine.\"")],
        theory: ("{D} smashed a car window at a gym and took a wallet and phone.", "{D} bought a used phone online and did not know it was stolen."),
        allocution: "\"I bought that phone from an online listing, and it looked fine. I did not break into any car, and I'm not the one in the black cap. I'm sorry that {V} lost a wallet and a phone. I should have been more careful about where the phone came from.\"",
        truths: ("{DL} had a prior case in this court, and a cap like the one on video was in {D.his} closet.", "The seller of the phone later confirmed the sale to {DL} and showed the thread."),
        defendant: [.direct("Did you smash that window?", "\"No, I did not. I have never been near that gym.\""),
               .direct("Where did the phone come from?", "\"I bought it from an online listing for $90. It looked fine, and the seller sent photos.\""),
               .direct("Do you have a receipt?", "\"Yes, an online receipt for a used phone. I showed it to the detective.\""),
               .direct("Did you check whether it was stolen?", "\"I did not. I should have looked closer. It looked like a normal phone.\""),
               .direct("Do you own a black cap?", "\"Yes, I own one, and I wear it often to work. It does not prove I was in that lot, and neither does a phone on my home network.\""),
               .direct("What do you want the court to know?", "\"I am sorry that someone lost a wallet and a phone. I should have been more careful about where the phone came from.\""),
               .cross("You were using a stolen phone, weren't you?", "\"I did not know it was stolen when I bought it. I thought I was buying a used phone from a normal seller, and I never suspected otherwise.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know that makes me look guilty. I did not do this.\""),
               .cross("A cap like the one on video was in your closet, wasn't it?", "\"Yes, I own several black caps, and it is the most common kind there is. Having one in a closet does not put me at that gym.\""),
               .cross("The phone connected to your home network, didn't it?", "\"Yes, because I used it at home. I did not know it was stolen.\""),
               .cross("$90 is a low price for a phone, isn't it?", "\"It was low, and I should have asked why. I was not thinking.\"")],
        openings: ("While {V} was in a gym, a side window of {V.his} car was smashed and a wallet and phone were taken, and a lot camera shows a person in a black cap at the car. {D} was found two days later using the phone, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a receipt for a used phone bought online for $90 and a seller who confirmed the sale. A buyer who got a bargain on a phone is not a burglar."),
        closings: ("A smashed window, a person in a black cap, and a stolen phone on {D}'s home network two days later. {D} owns a cap like that one, and was here before.", "A receipt, a seller who confirmed the sale, and a cap that thousands of people own. The State has not shown that {D} was at that gym or that {D.he} knew the phone was stolen when {D.he} bought it."),
        timeline: [(0, "While {V} is in a gym, a person in a black cap smashes a car window and takes a wallet and phone."), (2, "{D} is found using the stolen phone on a home network."), (3, "{D} says the phone came from an online listing and is charged.")],
        identified: "The phone traced to {DL}'s network.",
        mood: .indifferent,
        genders: ["D": .male])

    static let pickupLineSpeedingBack = SmallCases.make(
        key: "story.followup.pickupLineSpeedingBack",
        category: .traffic,
        headlines: ["Driver Races Through Soccer Field Parking Lot", "School Zone Driver Faces Second Reckless Driving Charge"],
        law: "recklessDriving",
        spec: "Drove carelessly and heedlessly in willful disregard of the rights and safety of others in a youth soccer field parking lot, on {DATE}.",
        ages: 21...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, at 5:30 p.m. on {DATE}, a pickup sped through a crowded youth soccer lot at about 40 miles per hour, swerving around parents and children. A coach recorded the plate. {D} owns the truck. {DL} says {D.he} was late to a work call and went slowly.",
        state: [E(.video, 3, "Coach Video", "A pickup swerves through the lot past parents and children."), E(.document, 2, "Plate Record", "The plate is registered to {DL}.")],
        defense: [E(.document, 1, "Work Call Log", "A call log shows {DL} was on a work call.")],
        role: "Youth soccer coach",
        exam: [.direct("What were you doing at the field that afternoon?", "\"I coach a youth soccer team. Practice ended at 5:25, and I was standing near the sideline with several parents while the kids walked to the parking lot.\""),
               .direct("What did you see at 5:30?", "\"A pickup came through the lot much too fast, swerving around parents and children who were walking to their cars. It did not slow down at the crosswalk.\""),
               .direct("How fast was it going?", "\"About forty miles per hour, I would estimate. That is far faster than anyone should drive in a lot full of children, and it was loud.\""),
               .direct("Did the truck hit anyone?", "\"No, but it missed a few kids by only a few feet. One mother pulled her little boy back by the arm as it went by.\""),
               .direct("What did you do?", "\"I took out my phone and recorded the plate and the truck as it left. I sent the video and the plate to the sheriff's office that evening.\""),
               .direct("What does the plate record show?", "\"The plate is registered to {DL}. I did not know the name until a deputy told me.\""),
               .direct("How did the parents react?", "\"They were frightened and angry. A parent shouted at the driver to slow down, and the truck did not slow down.\""),
               .cross("Was there a speed bump in the lot?", "\"There is one near the exit. The truck crossed it, and I did not hear it bottom out.\""),
               .cross("Could the truck have been going slower than forty?", "\"It is possible, but I do not think so. It was moving faster than a person can run.\""),
               .cross("Did the truck stop after it passed the children?", "\"No, it kept going, out through the exit and onto the road.\""),
               .cross("Did you see the driver's face?", "\"Not clearly. I saw a driver in the cab, but I could not tell who it was.\""),
               .cross("You are estimating speed, not measuring it, aren't you?", "\"Yes, that is true. I did not have a radar, and I am telling you what I saw and heard.\"")],
        theory: ("{D} sped through a youth soccer lot at forty miles per hour and swerved around children.", "{D} took a shortcut to a work call, drove slowly as {D.he} thought, and never meant to frighten anyone."),
        allocution: "\"I was late for a work call and took a shortcut through that lot, and I went slowly, or so I thought. I saw the children, and I'm sorry that parents were scared. I now understand how it looked to the coach who filmed me. I won't drive through a soccer lot again.\"",
        truths: ("{DL} had a prior case in this court for racing a school pickup line, and a parent yelled at {D.him} to slow down.", "The lot had a speed bump that {DL}'s truck crossed gently, and a parent confirmed the speed was low."),
        defendant: [.direct("Were you driving through the soccer lot that evening?", "\"Yes, I was. I was running late for a work call, and I cut through the lot as a shortcut to the main road.\""),
               .direct("How fast do you believe you were going?", "\"Slowly, I thought, but I know I was going faster than I should have. I did not look at the speedometer.\""),
               .direct("Did you see the children?", "\"I saw them, and I tried to steer around them. I should have stopped completely and waited.\""),
               .direct("What was the work call about?", "\"A client was waiting on a quote, and I was already ten minutes late. I was thinking about the call and not about the lot.\""),
               .direct("Did you cross the speed bump?", "\"Yes, near the exit, and I went over it gently. I did not hit it hard.\""),
               .direct("What do you want the parents to know?", "\"I am sorry that anyone was scared. I will never drive through a soccer lot again.\""),
               .cross("Parents were shouting at you to slow down, weren't they?", "\"I heard someone yelling, and I did not catch what was said. I should have stopped right then.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know that makes my story harder to believe. I should have remembered that case before I drove through that lot.\""),
               .cross("You swerved around parents and children, didn't you?", "\"I steered around people who were walking in front of me. I did not hit anyone, and I did not mean to come close to them.\""),
               .cross("A work call is not an emergency, is it?", "\"No, it is not. I let the hurry decide for me, and I regret it.\""),
               .cross("You did not stop after you passed them, did you?", "\"No, I kept going, because I did not realize how close it had been. I know now.\"")],
        openings: ("At 5:30 on {DATE}, a pickup sped through a crowded youth soccer lot at about forty miles per hour, swerving around parents and children. A coach recorded the plate, {D} owns the truck, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a work call log that shows why {D} was in a hurry, and a lot with a speed bump that the truck crossed gently. A parent will confirm the speed was low, and no one was touched."),
        closings: ("A truck, a crowded lot, and a coach's video that shows it swerving around children at a speed no lot allows. The plate belongs to {D}, who had been in this court before over reckless driving.", "A short trip to a work call, a speed bump taken gently, and no one hit. The State has not shown that {D} drove in willful disregard of anyone, only that {D.he} was hurried."),
        timeline: [(0, "5:25 p.m.: soccer practice ends and parents and children head for the lot."), (0, "5:30 p.m.: a pickup speeds through the lot, swerving around people, and a coach records the plate."), (1, "A deputy traces the plate to {D}."), (2, "{D} is charged with reckless driving.")],
        identified: "The plate recorded by the coach.",
        mood: .wantsConviction,
        genders: ["D": .male])

    static let altereCheckMailBack = SmallCases.make(
        key: "story.followup.altereCheckMailBack",
        category: .whiteCollar,
        headlines: ["Lost Wallet Card Used at Vape Shop", "Altered Check Defendant Faces Card Fraud Charge"],
        law: "cardFraud",
        spec: "Used a financial transaction card of {V} without consent to obtain $430 in goods, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} lost a wallet at a bus stop. Within an hour, {V.his} debit card was used four times at a vape shop for $430. The clerk picked {D} from a photo. {DL} says a friend let {D.him} use the card.",
        state: [E(.video, 3, "Shop Camera", "{D} swipes a card four times at the counter."), E(.document, 2, "Bank Record", "Four charges totaling $430 an hour after the wallet was lost.")],
        defense: [E(.statement, 1, "Friend's Card", "{DL} says a friend handed over the card.")],
        role: "Vape shop clerk",
        exam: [.direct("What is your job at the vape shop?", "\"I am a clerk. I work the counter on most afternoons, and I handle sales, cards, and age checks.\""),
               .direct("What happened that afternoon?", "\"A customer came in about an hour after noon and used a debit card at my counter four times. Each swipe was for a small amount, and all four came to about $430.\""),
               .direct("Who was that customer?", "\"{DL}. I picked {D.him} out of a photo array when a deputy showed it to me a few days later.\""),
               .direct("What does your shop camera show?", "\"It shows {DL} at the counter, handing over a card and swiping it four times. The time stamp matches the bank's records.\""),
               .direct("What did {DL} say about the card?", "\"{D.He} said it belonged to a friend, and the friend had told {D.him} it was fine to use it. I asked who the friend was, and {D.he} would not say.\""),
               .direct("Did you check the card?", "\"I looked at the name on it, and it did not match {D.him}. I should have asked more, but {D.he} seemed calm and sure.\""),
               .direct("What did you do afterward?", "\"I told my manager and called the sheriff's office when the bank flagged the charges. I gave a deputy the video.\""),
               .cross("{DL} said it was a friend's card, didn't {D.he}?", "\"Yes, that is what {D.he} said. But I saw no friend in the shop.\""),
               .cross("Did anyone else come in with {DL}?", "\"No, {D.he} was alone at the counter the whole time. I did not see a friend in the shop, in the lot, or at the door.\""),
               .cross("Was {DL} nervous?", "\"Not particularly. {D.He} was calm and the swipes were quick, which is part of why I did not think anything was wrong until the bank called.\""),
               .cross("You identified {DL} from a photo array, didn't you?", "\"Yes, a few days later. I picked {D.him} out, and I was fairly sure.\""),
               .cross("Did the card have the owner's name on it?", "\"Yes, and it did not match {DL}'s. That is how I know it was not {D.his}.\"")],
        theory: ("{D} used a lost debit card four times at a vape shop.", "{D} used a card a friend handed over and did not know it was lost."),
        allocution: "\"A guy from work gave me that card and told me I could use it, and I believed it was theirs. I did not know it was {V}'s. I'm sorry that {V.he} lost the money and had to deal with a bank. I'll pay back the four hundred thirty dollars, and I'll help find who gave it to me.\"",
        truths: ("{DL} had a prior case in this court for a mail check, and the friend does not exist.", "A friend did hand over the card and said it was his own."),
        defendant: [.direct("Whose card did you use?", "\"A friend from work handed it to me and said it was fine to use. I believed the card was {D.his}.\""),
               .direct("Why did you use it?", "\"I needed a few things and did not have cash on me. The friend told me to use it, and I did.\""),
               .direct("Did you know it was lost?", "\"No. I did not know it belonged to {V}, and I did not know anyone had lost a wallet.\""),
               .direct("Why four swipes?", "\"I made a few small purchases, one after another. I did not add up the total.\""),
               .direct("Who is the friend?", "\"A guy from work. I do not know where he is now, and I have not been able to reach him since.\""),
               .direct("What will you do about it?", "\"I will pay back the $430 and help find who gave me the card. I am sorry that {V} lost money.\""),
               .cross("The name on the card was not yours, was it?", "\"No. I assumed my friend had a card with a name I did not know.\""),
               .cross("You never asked your friend about the name on the card, did you?", "\"No. I should have asked, and I did not.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know that makes this look like a pattern. I did not know the card was stolen.\""),
               .cross("You do not have a name for the friend, do you?", "\"I know his first name and where he works. I have given both to the detective.\""),
               .cross("The swipes were within an hour of the wallet being lost, weren't they?", "\"So the bank says. I did not know when the wallet was lost.\"")],
        openings: ("{V} lost a wallet at a bus stop, and within the hour {V.his} debit card was used four times at a vape shop for $430. The shop's camera shows {D} swiping it, the clerk picked {D.him} from a photo, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a person who says a friend from work handed over the card and said it was fine to use. {D} used it in front of a camera and a clerk, which is not how a thief acts."),
        closings: ("Four swipes in an hour, a name on the card that was not {D}'s, and a friend nobody can find or name. The camera and the bank record agree on every minute.", "A friend's card, a shopper who did not know it was lost, and a camera that shows {D} openly at the counter. The State has not shown that {D} knew the card was stolen when it was handed over."),
        timeline: [(0, "Noon: {V} loses a wallet at a bus stop."), (0, "1 p.m.: a card from the wallet is swiped four times at a vape shop for $430."), (1, "The clerk reports the card use after the bank flags it."), (3, "The clerk picks {D} from a photo and {D} is charged.")],
        identified: "The shop clerk's photo pick.",
        mood: .indifferent)

    static let rentalCarPillsBack = SmallCases.make(
        key: "story.followup.rentalCarPillsBack",
        category: .drugs,
        headlines: ["Pills Found in Hotel Room Safe After Noise Complaint", "Rental Car Defendant Faces New Pill Charge"],
        law: "possSchedII",
        spec: "Knowingly possessed fentanyl-laced pills, a Schedule II controlled substance, on {DATE}.",
        ages: 22...43,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, after a noise complaint at a highway hotel on {DATE}, deputies found 11 blue pills in the room safe. The room was rented by {D}. {DL} says the safe had been left locked by a prior guest and was not opened by {D.him}.",
        state: [E(.physical, 3, "Pills in Safe", "Eleven blue pills in a room safe rented to {DL}."), E(.forensic, 2, "Lab Report", "The pills test positive for fentanyl.")],
        defense: [E(.document, 1, "Prior Guest", "A front desk log shows another guest in the room the night before.")],
        role: "Deputy",
        exam: [.direct("What is your assignment?", "\"I am a deputy with the sheriff's office. I work patrol, and that night I responded to a noise complaint at a highway hotel.\""),
               .direct("What did you find at the room?", "\"Loud television and voices coming from the room. The front desk said the room was rented to {DL}.\""),
               .direct("What did you find inside?", "\"Eleven blue pills in a room safe. We opened it with the hotel manager and a master code.\""),
               .direct("Who rented the room?", "\"The registration shows {DL}. The room had been rented for two nights.\""),
               .direct("What did the lab find?", "\"The pills tested positive for fentanyl. The lab report is in the file.\""),
               .direct("Was the safe locked?", "\"Yes, it was locked when we arrived. We needed the hotel's code to open it.\""),
               .direct("What did {DL} say?", "\"{D.He} said the pills were not {D.his} and that {D.he} had never opened the safe. {D.He} said {D.he} was watching TV.\""),
               .cross("Did the hotel keep a log of prior guests?", "\"Yes, the front desk keeps one, and it shows another guest in that room the night before. I have the log in the file.\""),
               .cross("Was the safe code reset between guests?", "\"It is supposed to be reset at checkout. I do not know whether housekeeping did it that day, and the hotel manager could not say either.\""),
               .cross("Was there any sign {DL} had opened it?", "\"I did not see any sign of that. We did not take fingerprints from the safe, so I cannot say who touched it last.\""),
               .cross("Was anything else found in the room?", "\"No, nothing else that was illegal. The rest of the room was clean, with a few beverage cans and a bag of chips.\""),
               .cross("You cannot say who put the pills in the safe, can you?", "\"No, I cannot. I know only whose room it was and what was in it.\"")],
        theory: ("{D} kept eleven fentanyl pills in a hotel room safe.", "{D} never opened the safe, and the pills were left by a prior guest."),
        allocution: "\"Those pills were not mine. The safe had been locked by a prior guest, and I never opened it. I was watching TV when the deputies came. I'm sorry for the noise complaint and for the alarm it caused at the hotel. I'd ask the court to look at who stayed there before me.\"",
        truths: ("{DL} had a prior case in this court for pills in a rental car, and had set the safe code to {D.his} own birthday.", "The safe code was still the prior guest's, and {DL} had never opened it."),
        defendant: [.direct("Are those pills yours?", "\"No, they are not mine. I have never seen them before the deputies opened the safe.\""),
               .direct("Did you open the safe?", "\"No, I never opened it. I did not use it, and I did not know there was anything inside.\""),
               .direct("Why was the room loud?", "\"The television was on, and I had some friends over. I did not think it was that loud.\""),
               .direct("What did you do when the deputies came?", "\"I opened the door and answered every question. I did not hide anything.\""),
               .direct("Who stayed in the room before you?", "\"I was told another guest had it the night before. The front desk log shows that.\""),
               .direct("What do you want the court to know?", "\"I am sorry for the noise complaint and for the alarm at the hotel. I would ask the court to look at who stayed there before me.\""),
               .cross("The room was rented to you, wasn't it?", "\"Yes, and I know that I am responsible for it. But I did not use the safe.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know how that looks. I did not put those pills there.\""),
               .cross("The safe code was your birthday, wasn't it?", "\"I did not set a code. I never opened it, so I do not know what it was.\""),
               .cross("You had friends in the room, didn't you?", "\"Yes, a few. I do not know what any of them did.\""),
               .cross("You did not report the safe to the front desk, did you?", "\"No, because I did not know there was anything wrong with it.\"")],
        openings: ("After a noise complaint at a highway hotel, deputies found eleven blue pills in the room safe, and the lab says they contain fentanyl. The room was rented to {D}, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a front desk log showing another guest in the room the night before. A safe that was locked and a defendant who never opened it do not add up to possession."),
        closings: ("The room was {D}'s, the safe was in the room, and the pills were in the safe. A person who rents a room is responsible for what is in it, and {D} had been before this court over pills.", "A prior guest, a safe nobody reset, and no proof that {D} ever touched it. The State has not shown that {D} knew the pills were there, and the lab cannot tell us who put them in."),
        timeline: [(-1, "A prior guest stays in the room."), (0, "A noise complaint brings deputies to the hotel."), (0, "Deputies open the locked safe with the hotel and find eleven blue pills."), (1, "The lab finds fentanyl and {D} is charged.")],
        identified: "A deputy opening the safe.",
        mood: .indifferent)

    static let parkingLotSleeperBack = SmallCases.make(
        key: "story.followup.parkingLotSleeperBack",
        category: .traffic,
        headlines: ["Revoked Driver Caught Waiting in Car Wash Line", "Sleeping Driver Case Defendant Charged With Driving While Revoked"],
        law: "dwlrImpaired",
        spec: "Operated a motor vehicle on a public street while {D.his} license was revoked for an impaired driving conviction, on {DATE}.",
        ages: 35...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a deputy saw {D} pull a sedan out of a drive-through car wash onto a county road on {DATE}. {DL}'s license was revoked for an impaired driving conviction. {DL} says a friend was driving and swapped seats when the deputy turned on lights.",
        state: [E(.video, 3, "Deputy Dashcam", "{D} is in the driver's seat as the sedan leaves the wash."), E(.document, 2, "DMV Record", "{DL}'s license is revoked for impaired driving.")],
        defense: [E(.statement, 1, "Friend's Account", "A friend says {D.he} was driving.")],
        role: "Deputy",
        exam: [.direct("What is your assignment?", "\"I am a sheriff's deputy on patrol. I do traffic enforcement, and I look for drivers with suspended or revoked licenses.\""),
               .direct("What did you see that morning?", "\"I was parked near a car wash on a county road. I saw a sedan come out of the exit, and the person in the driver's seat was {DL}.\""),
               .direct("How did you know it was {DL}?", "\"I had seen {D.him} before, and the dashcam shows {D.him} in the driver's seat as the car leaves the wash. I ran the plate and the name matched.\""),
               .direct("What did the DMV record show?", "\"{DL}'s license was revoked for an impaired driving conviction. The revocation was still in effect that morning, with no limited privilege on file.\""),
               .direct("Where did the sedan go?", "\"Onto the county road. I followed it for about ten minutes, and then I turned on my lights.\""),
               .direct("What happened when you stopped it?", "\"{DL} was in the driver's seat, and a friend was in the passenger seat. {DL} said the friend had been driving.\""),
               .direct("Did you see anyone switch seats?", "\"No, I did not. I watched the car for the entire ten minutes and saw no one move or lean across, and I saw the same outline in the driver's seat the whole way.\""),
               .cross("Could someone have switched seats at the car wash?", "\"It is possible. I did not see inside the car at the exit.\""),
               .cross("The dashcam does not show a face, does it?", "\"It shows a person in the driver's seat. The face is not clear.\""),
               .cross("Did the friend say who was driving?", "\"Yes, the friend said {DL} was driving at the exit. I did not hear what the friend said about the stop.\""),
               .cross("Was the car registered to {DL}?", "\"No, it was registered to a relative of {DL}'s. I called the relative afterward, and the relative said {DL} had borrowed it that morning.\""),
               .cross("You did not see {DL} swap seats on the road, did you?", "\"No, I did not. I kept the sedan in view for ten minutes, and the person at the wheel never changed, as far as I could tell.\"")],
        theory: ("{D} drove a sedan out of a car wash while {D.his} license was revoked for impaired driving.", "A friend drove the sedan, and {D} only took the wheel after the deputy turned on the lights."),
        allocution: "\"I was not driving. A friend drove the car through the car wash, and we swapped seats when the deputy turned on the lights. I know my license was revoked. I'm sorry for the confusion on that road. I'll stay in the passenger seat until my license is restored.\"",
        truths: ("{DL} had a prior case in this court for being asleep in a running car, and the sedan's seat was set for {D.his} height.", "The friend had a clean license and was in the car, as the car wash receipt shows."),
        defendant: [.direct("Did you drive that car?", "\"No, I did not. A friend drove it through the car wash, and I rode along.\""),
               .direct("Why did you switch seats?", "\"When the deputy turned on the lights, my friend asked me to take the wheel because my friend was nervous about being stopped. I never stopped to think about what it would look like.\""),
               .direct("Did you know your license was revoked?", "\"Yes, I knew, and I never would have driven if I had a choice.\""),
               .direct("Where were you sitting at the car wash?", "\"In the passenger seat, as I recall. The dashcam is blurry and I do not know why the deputy thinks it was me.\""),
               .direct("What did you say to the deputy?", "\"I told the deputy the truth, that my friend had been driving. The deputy did not believe me.\""),
               .direct("What do you regret?", "\"I am sorry for the confusion on that road. I will stay in the passenger seat until my license is restored.\""),
               .cross("You were revoked for impaired driving, weren't you?", "\"Yes, and that is why I do not drive. I have not driven since.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, I was, and I know it makes this hard to believe.\""),
               .cross("The sedan's seat was set for your height, wasn't it?", "\"It was set for someone my height. My friend and I are about the same.\""),
               .cross("Your friend has a clean license, doesn't your friend?", "\"Yes, my friend does, and I can give the court the name. I do not want to cause trouble, but I will if I am asked.\""),
               .cross("You were in the driver's seat when the deputy stopped the car, weren't you?", "\"Yes, because my friend swapped with me when the lights came on. I should not have moved.\"")],
        openings: ("A deputy saw {D} behind the wheel of a sedan leaving a car wash, followed it ten minutes down a county road, and stopped it. {DL}'s license was revoked for impaired driving, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a friend who says {D} was not driving. A deputy who watched a car for ten minutes did not see anyone switch seats, but a friend with a clean license was inside."),
        closings: ("The dashcam shows {D} in the driver's seat as the sedan leaves the wash, the DMV shows a revocation for impaired driving, and the deputy never saw anyone switch seats on the road.", "A blurry video, a friend with a clean license, and a seat set for two people of the same height. The State has not shown beyond a reasonable doubt who was at the wheel when that car left the wash."),
        timeline: [(0, "Morning: a sedan leaves a car wash onto a county road and a deputy follows it."), (0, "Ten minutes later: the deputy turns on lights and stops the sedan."), (0, "The deputy finds {D}, whose license is revoked, in the driver's seat."), (1, "{D} says a friend was driving, and {D} is charged.")],
        identified: "A deputy's dashcam.",
        mood: .indifferent)

    static let roadBlockadeBack = SmallCases.make(
        key: "story.followup.roadBlockadeBack",
        category: .traffic,
        headlines: ["Flagger Hit by Mirror as Driver Speeds Through Road Work Zone", "Protest Driver Faces Reckless Driving Charge"],
        law: "recklessDriving",
        spec: "Drove carelessly and heedlessly through a road work zone in willful disregard of the safety of {V}, a traffic flagger, on {DATE}.",
        ages: 30...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}, a flagger at a road work zone, held a stop sign when a sedan driven by {D} sped around the sign and passed within a foot of {V}. The side mirror clipped {V.his} arm. {DL} says {D.he} thought the flagger had waved cars through.",
        state: [E(.video, 3, "Work Zone Camera", "A sedan passes the stop sign and clips {V}'s arm."), E(.physical, 2, "Bruise", "A bruise on {V}'s arm and a broken mirror cover on the road.")],
        defense: [E(.statement, 1, "Waved Through", "{DL} says the flagger waved.")],
        role: "Traffic flagger",
        exam: [.direct("What is your job at the road work zone?", "\"I am a traffic flagger. I hold a stop and slow sign at lane closures and direct drivers through the work zone one direction at a time.\""),
               .direct("What happened that morning?", "\"I was standing in the lane holding the stop sign when a sedan sped around the sign. It passed within a foot of me and the side mirror clipped my arm.\""),
               .direct("Did you wave the driver through?", "\"No. My sign was turned to stop, and I was holding it with both hands the whole time. I never waved anyone through while that sedan was coming.\""),
               .direct("What does the work zone camera show?", "\"It shows the sedan passing the stop sign without slowing much and the mirror touching my arm. You can see my arm jerk back.\""),
               .direct("How were you hurt?", "\"I had a bruise on my upper arm and a sore shoulder for about a week. A broken mirror cover was lying on the road, and a worker photographed it.\""),
               .direct("What did {DL} say to you afterward?", "\"{D.He} said {D.he} thought I had waved cars through, and that {D.he} did not see the sign at first. {D.He} was apologetic once {D.he} stopped.\""),
               .direct("How has this changed your work?", "\"I am more nervous now. I step back every time a car comes fast, and I stay close to the cones.\""),
               .cross("Was the sign clearly visible?", "\"It is a bright red octagon on a pole, and I was standing in the lane in a reflective vest. A worker nearby says it could not be missed.\""),
               .cross("Did {DL} slow down before the clip?", "\"A worker says {D.he} slowed for a moment before passing the sign. I did not see that myself, because I was watching my own feet.\""),
               .cross("Was the lane closed with cones?", "\"Yes, there were cones and a sign well before the work zone. The lane was clearly marked as closed.\""),
               .cross("Did {DL} stop after clipping you?", "\"Not right away. {D.He} went on a short way, and then stopped and came back, and a deputy was already there.\""),
               .cross("You did not see the driver's face, did you?", "\"Not clearly, because it happened fast. I saw a driver and a sedan, and the camera got the plate.\"")],
        theory: ("{D} sped past a stop sign and clipped a flagger's arm with a mirror.", "{D} thought cars were being waved through and slowed before the clip."),
        allocution: "\"I did not see the flagger at first, and I thought the cars were being waved through. A mirror touched {V}'s arm, and I'm so sorry. I was going a little fast, and I should have slowed to a stop. I'll treat every work zone with care from now on.\"",
        truths: ("{DL} had a prior case in this court for driving through protesters and said, 'Move,' before passing.", "A worker confirms the sign was out and the lane was closed, but also that {DL} slowed before the clip."),
        defendant: [.direct("Did you see the flagger's stop sign?", "\"Not at first. I was watching the lane and then the cones, and I did not look up at the sign until I was nearly there.\""),
               .direct("What did you think when you reached the work zone?", "\"I thought the cars were being waved through. I saw a car ahead of me pass, and I followed it without thinking.\""),
               .direct("Did you hit the flagger?", "\"A mirror touched {V.his} arm. I did not feel it at the time, and I did not know until I looked in my rearview mirror.\""),
               .direct("Were you in a hurry that morning?", "\"A little. I was late for work, and I should have slowed to a stop and waited for the flagger to wave.\""),
               .direct("What did you do after that?", "\"I stopped a short way down the road and went back. A deputy was already talking to the flagger, and I told the deputy what I thought.\""),
               .direct("What do you want to say to the flagger?", "\"I am so sorry. I will treat every work zone with care from now on, and I will stop whenever I am not sure.\""),
               .cross("You passed the stop sign, didn't you?", "\"Yes, and I should have stopped. I misread the situation, and I am sorry.\""),
               .cross("You came before this court in {PRIORDATE} over {PRIOR}, didn't you?", "\"Yes, and I know how that looks beside this charge. I did not mean to hurt anyone then, and I did not now.\""),
               .cross("You said Move before passing, didn't you?", "\"I may have said something under my breath. I was nervous, and I wanted to get through the work zone quickly.\""),
               .cross("The lane was closed with cones, wasn't it?", "\"Yes, with cones and a sign. I did not read them as carefully as I should have.\""),
               .cross("You did not stop right after the clip, did you?", "\"Not right away. I did not realize I had touched anyone until I looked in the mirror, and then I stopped.\"")],
        openings: ("At a road work zone, {V}, a flagger, held a stop sign when a sedan driven by {D} sped around it, passed within a foot of {V}, and clipped {V.his} arm with a mirror. A camera recorded it, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a driver who thought the flagger had waved cars through and who slowed before the clip. A worker confirms {D} slowed down, and a misread signal is not a willful disregard of safety."),
        closings: ("A stop sign, a closed lane marked with cones, a clipped arm, and a mirror cover on the road. The video shows {D} passing the sign while {V} stood in the lane.", "A misread wave, a driver who was late for work, and a mirror that touched an arm. The State has not shown that {D} drove in willful disregard of {V} or of anyone's safety in that zone."),
        timeline: [(0, "Morning: a lane closes for road work and {V} holds a stop sign in the lane."), (0, "10 a.m.: a sedan driven by {D} passes the sign and clips {V}'s arm with a mirror."), (1, "A deputy speaks with {D}, who returns to the scene, and {D} is charged with reckless driving.")],
        identified: "The work zone camera plate.",
        mood: .wantsConviction)

    static let restraintDeathBack = SmallCases.make(
        key: "story.followup.restraintDeathBack",
        category: .publicOrder,
        headlines: ["Ex-Officer Falsifies Log at Security Job", "Former Detention Officer Faces Obstruction Charge"],
        law: "obstruction",
        spec: "Willfully and unlawfully obstructed justice by falsifying a patrol log submitted to a police investigation, on {DATE}.",
        ages: 30...56,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D}, now a security guard at a warehouse, was asked by police for patrol logs after a theft. {DL} wrote in rounds that were never walked. Video shows the guard post empty for three hours. {DL} says the entries were written from memory later.",
        state: [E(.video, 3, "Gate Camera", "The guard post is empty from 1 to 4 a.m."), E(.document, 2, "Patrol Log", "Hourly rounds are logged as walked during those hours.")],
        defense: [E(.statement, 1, "From Memory", "{DL} says the log was filled in later and not meant to deceive.")],
        role: "Warehouse manager",
        exam: [.direct("What is your position at the warehouse?", "\"I am the warehouse manager. I oversee operations, hire the security guards through a contractor, and I am the person police call when something goes missing.\""),
               .direct("What happened that led police to ask for the patrol log?", "\"There was a theft from the loading yard overnight. Police asked for the guard's patrol log to see who had been walking the grounds, and I gave them {DL}'s log.\""),
               .direct("What did the log say?", "\"It lists hourly rounds as walked, every hour from one until four in the morning. Each entry has a time and a short note, all in {DL}'s handwriting.\""),
               .direct("What does the gate camera show?", "\"The guard post is empty from one to four. There is nobody at the desk, and nobody walking the yard on camera in that window.\""),
               .direct("How did {DL} explain it?", "\"{D.He} said the entries were written from memory the next morning, and that some were not exact. {D.He} did not say that when the police first asked.\""),
               .direct("Were you told the post would be empty?", "\"No. I was not told that anyone had left the post, and a guard is not supposed to leave it for three hours.\""),
               .direct("Why does this matter to you?", "\"The theft was in that window, and false rounds sent the investigation in the wrong direction for days. We lost time we could not get back.\""),
               .cross("Did {DL} say a coworker was sick that night?", "\"I have heard that, but I was not told that night. A sick coworker is a reason to call me, not to leave the post.\""),
               .cross("Did {DL} complete some rounds?", "\"I do not know. The cameras do not show the interior of every building.\""),
               .cross("Was the log written before or after the theft was reported?", "\"I believe it was written after. The handwriting is neat, and the ink looks the same on every line.\""),
               .cross("Could {DL} have walked rounds in places the camera does not see?", "\"Yes, it is possible. The camera shows the gate and the post, not every corner of the yard.\""),
               .cross("You cannot say what {DL} was doing from one to four, can you?", "\"No, I cannot. I know only what the camera shows and what the log says.\"")],
        theory: ("{D} filled a patrol log with rounds that were never walked and gave it to police.", "{D} wrote the log from memory the next morning and did not mean to mislead anyone."),
        allocution: "\"I wrote some of those rounds from memory the next morning, and a few of them were not exact. I should have said so when the police asked for the logs. I'm sorry for the confusion in their investigation. I take my work as a guard seriously, and I'll keep honest logs.\"",
        truths: ("{DL} had a prior case in this court as a detention officer and wrote the log after the theft was reported.", "{DL} was out of the post because of a sick coworker and the manager was told."),
        defendant: [.direct("Did you walk the rounds that night?", "\"I walked some of them. I walked the first two, and then I left the post for a while.\""),
               .direct("Why did you leave the post?", "\"A coworker was sick, and I helped get the coworker to a car. I told the manager's answering service, but I do not know that it was passed on.\""),
               .direct("When did you write the log?", "\"The next morning, from memory. I was tired and I filled in the hours as best I could.\""),
               .direct("Were all the entries accurate?", "\"A few were not exact. I should have said so when the police asked for the logs.\""),
               .direct("Why did you not tell the police that at first?", "\"I was afraid I would be in trouble, and I did not want to lose the job. I take my work as a guard seriously, and I should have been honest.\""),
               .direct("What will you do differently?", "\"I will write the logs as I work and keep them honest. I am sorry for the confusion in the investigation.\""),
               .cross("The log says hourly rounds were walked from one to four, doesn't it?", "\"Yes, it does, and I wrote some of those from memory. They were not all exact.\""),
               .cross("The post was empty for three hours, wasn't it?", "\"Yes, the camera shows that, and I will not argue with it. I was helping a coworker part of that time.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know that makes this look worse. I did not write the log to mislead anyone.\""),
               .cross("You wrote the log after the theft was reported, didn't you?", "\"I wrote it the next morning, and the theft was reported later that day. I did not know about it when I wrote it.\""),
               .cross("You did not tell the manager about the sick coworker, did you?", "\"I told the answering service. I did not call the manager's cell phone, and I should have.\"")],
        openings: ("After a theft at a warehouse, police asked guard {D} for patrol logs, and {DL} handed over hourly rounds that were never walked. The gate camera shows the post empty from one to four in the morning, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a guard who filled in a log from memory the next morning after helping a sick coworker. The entries were imperfect, but there was no plan to deceive anyone."),
        closings: ("A log that says hourly rounds were walked, a camera that shows an empty post for three hours, and a theft that happened in that window. False entries sent the police the wrong way.", "A tired guard, a sick coworker, and a log written from memory the next morning. The State has not shown that {D} meant to hinder any investigation, only that the paperwork was sloppy."),
        timeline: [(0, "1 a.m.: the guard post at the warehouse is empty and a theft occurs in the loading yard."), (1, "The next morning, {D} writes hourly entries into the patrol log from memory."), (2, "Police ask the manager for the patrol log and the gate camera video."), (3, "Police compare the log to the video and {D} is charged with obstruction.")],
        identified: "The gate camera.",
        mood: .indifferent)

    static let exHouseKeyBack = SmallCases.make(
        key: "story.followup.exHouseKeyBack",
        category: .property,
        headlines: ["Ex-Tenant Charged After Entering Former Landlord's Rental", "Former Partner Case Defendant Faces Trespass Charge"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a landlord, after being notified not to enter, on {DATE}.",
        ages: 28...53,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} walked into a vacant duplex owned by {V}, {DL}'s former landlord, to get a washer left behind. A no-trespass letter had been mailed to {DL} two weeks earlier. {DL} says the washer was {D.his} and the door was open.",
        state: [E(.document, 3, "No-Trespass Letter", "A certified letter signed for by {DL} two weeks earlier."), E(.video, 2, "Door Camera", "{D} walks into the duplex and out with a washer hose.")],
        defense: [E(.document, 1, "Washer Receipt", "A receipt for a washer in {DL}'s name.")],
        role: "Landlord",
        exam: [.direct("What is your connection to the duplex?", "\"I own the duplex. It has been vacant since {DL} moved out, and I have been preparing it to rent again.\""),
               .direct("What notice did you give {DL}?", "\"I sent a no-trespass letter by certified mail two weeks before this happened. {DL} signed for it, and I have the green card.\""),
               .direct("What does your door camera show?", "\"It shows {DL} walking into the vacant unit and walking out with a washer hose in hand. It is a short clip, about four minutes.\""),
               .direct("Was the door open?", "\"It was unlocked for the cleaners, who were coming that morning. That is the only reason {DL} could get in.\""),
               .direct("Whose washer is in the unit?", "\"A washer was left in the laundry room when {DL} moved out. {DL} says it belongs to {D.him}, and I say it was in my unit.\""),
               .direct("What did you do?", "\"I called the sheriff's office as soon as I saw the video. I gave a deputy the letter and the green card.\""),
               .direct("Why did you not let {DL} have the washer?", "\"{DL} never asked me. If {D.he} had asked, I would have arranged a time to hand it over with someone present.\""),
               .cross("{DL} says the washer is {D.his}, doesn't {D.he}?", "\"Yes, and {D.he} has a receipt. I do not dispute that {D.he} bought a washer.\""),
               .cross("Did {DL} call you before going in?", "\"{D.He} called once, a few days before. I did not call back, and I should have.\""),
               .cross("Was anything damaged?", "\"No, nothing was damaged that I could find. {DL} took only a hose, and the unit was clean when I walked it afterward.\""),
               .cross("Did your cleaner say the door would be left open?", "\"My cleaner left the door unlocked that morning. I told the cleaner to do so.\""),
               .cross("You do not know what {DL} thought about the door, do you?", "\"No, I cannot say. I know only that the door was open.\"")],
        theory: ("{D} entered a vacant duplex after a written no-trespass notice and left with a washer hose.", "{D} went in to retrieve {D.his} own washer through an open door."),
        allocution: "\"I went into that duplex to get my washer, and the door was open. I did not read the letter closely, and I called once about it. I'm sorry to {V}, my former landlord, for coming without permission. I should have waited and asked for the washer through the proper channel.\"",
        truths: ("{DL} had a prior case in this court over burglary of an ex's home and had been told in writing not to return.", "{V}'s own cleaner had said the unit would be left open and the washer was truly {DL}'s."),
        defendant: [.direct("Did you read the no-trespass letter?", "\"Not closely. I signed for it, but I did not read every line.\""),
               .direct("Why did you go into the duplex?", "\"To get my washer. I bought it before I moved, and it was left in the laundry room.\""),
               .direct("Was the door open?", "\"Yes, it was open when I got there. I did not force anything.\""),
               .direct("Did you ask first?", "\"I called once and did not get a call back. I should have waited and asked again.\""),
               .direct("What did you take?", "\"A washer hose. I did not take the washer, because I could not carry it alone.\""),
               .direct("What do you want the landlord to know?", "\"I am sorry for coming without permission. I should have waited and asked for the washer through the proper channel.\""),
               .cross("You signed for the certified letter, didn't you?", "\"Yes, and I know what it said now. I did not read it carefully then.\""),
               .cross("You were told in writing not to return, weren't you?", "\"Yes, and I forgot about it when I thought of my washer.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know that makes me look like someone who does not listen. I only wanted the washer.\""),
               .cross("You went in when nobody was home, didn't you?", "\"Yes, because the door was open. I would not have gone in if someone had been there.\""),
               .cross("You left with a hose, not the washer, didn't you?", "\"Yes, because I could not move the washer. I planned to come back for it.\"")],
        openings: ("Two weeks after {V} mailed {D} a certified no-trespass letter, a door camera caught {D} walking into {V}'s vacant duplex and out with a washer hose. {DL} signed for the letter, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a receipt for a washer in {D}'s name and a door that was left unlocked for the cleaners. A tenant who goes for {D.his} own appliance, in daylight, on camera, is not trespassing in bad faith."),
        closings: ("A certified letter signed for two weeks earlier and a camera that shows {D} walking into the duplex. {D} had been in this court before and knew what a written notice meant.", "A receipt, a washer left behind, and a door standing open for the cleaners. The State has not shown that {D} meant to trespass rather than reclaim something that was {D.his} own."),
        timeline: [(-14, "{V} mails {D} a certified no-trespass letter, and {D} signs for it."), (0, "The cleaners leave the vacant duplex unlocked and {D} walks in."), (0, "The door camera records {D} leaving with a washer hose."), (1, "{V} gives the video and the letter to a deputy and {D} is charged.")],
        identified: "The door camera.",
        mood: .divided)

    static let truckStopKillerBack = SmallCases.make(
        key: "story.followup.truckStopKillerBack",
        category: .traffic,
        headlines: ["Trucker Runs Weigh Station Lane at Speed", "Trucker From Truck Stop Case Charged With Reckless Driving"],
        law: "recklessDriving",
        spec: "Drove a tractor-trailer carelessly and heedlessly in willful disregard of the rights and safety of others at a weigh station, on {DATE}.",
        ages: 40...58,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} drove a tractor-trailer through a closed weigh station lane at 45 miles per hour, forcing an inspector to leap aside. Dashcam shows the trailer miss a cone by feet. {DL} says the ramp sign was missing and the brakes were soft.",
        state: [E(.video, 3, "Station Camera", "A tractor-trailer passes the closed sign at speed as an inspector jumps clear."), E(.document, 2, "Inspector Report", "The inspector reports the lane was marked closed with cones.")],
        defense: [E(.document, 1, "Brake Record", "A repair note for soft brakes the week before.")],
        role: "Weigh station inspector",
        exam: [.direct("What is your job?", "\"I am an inspector at a weigh station. I check trucks for weight, equipment, and paperwork, and I stand near the lanes while they go through.\""),
               .direct("What happened that morning?", "\"A tractor-trailer came down the closed lane at speed. I was standing near the cones, and I had to jump aside to get out of its way.\""),
               .direct("Was the lane marked closed?", "\"Yes. There were cones across the lane and a sign at the ramp that said the lane was closed. I put them out myself that morning.\""),
               .direct("How fast was the truck going?", "\"The station camera clocked it at about forty-five miles per hour. That is much too fast for a weigh station lane.\""),
               .direct("Did the truck hit anyone?", "\"No, but it missed me by a few feet and it missed a cone by feet. I felt the wind from the trailer.\""),
               .direct("What does your report say?", "\"The lane was marked closed with cones and a sign. I wrote down the plate and the time, and I sent it to the highway patrol.\""),
               .direct("How did you feel?", "\"Shaken. I have been doing this for eleven years and never had to leap out of the way.\""),
               .cross("Was the sign at the ramp standing that morning?", "\"I put it up myself. I have heard that it was found on the ground the next morning, so it may have been knocked down.\""),
               .cross("Could the driver have missed the cones?", "\"They were orange and about three feet tall. A driver who was paying attention would not miss them.\""),
               .cross("Did the truck brake?", "\"I did not see brake lights until it was almost past the cones. Then it slowed.\""),
               .cross("Did the truck stop after?", "\"Yes, down the road, and the driver came back and spoke with me.\""),
               .cross("You cannot say whether the brakes were soft, can you?", "\"No, I cannot. I am not a mechanic, and I did not inspect that truck.\"")],
        theory: ("{D} drove a tractor-trailer through a closed weigh station lane at forty-five miles per hour.", "{D} had soft brakes and did not see a sign before the cones came up."),
        allocution: "\"I was running late, and my brakes were soft that morning, and I did not see a sign at the ramp. I came through at forty-five miles an hour, and I'm sorry that the inspector had to leap aside. I'll never run a scale without checking the lane.\"",
        truths: ("{DL} had a prior case in this court for truck stop killings and looked back twice before speeding up.", "A repair shop confirms the soft brakes and the sign was found on the ground the next morning."),
        defendant: [.direct("Did you see the closed lane?", "\"Late. I did not see a sign at the ramp, and the cones came up quickly.\""),
               .direct("Why were you going so fast?", "\"I was running late, and my brakes were soft that morning. I had noted it a week before but had not fixed it.\""),
               .direct("Did you report the brakes?", "\"No, I did not. I should have taken the truck in sooner.\""),
               .direct("Where was the inspector?", "\"Near the cones. I saw the inspector jump aside, and I felt sick to my stomach.\""),
               .direct("What did you do afterward?", "\"I stopped down the road and walked back to apologize. I spoke with the inspector and gave my name.\""),
               .direct("What will you do differently?", "\"I will never run a scale without checking the lane. I am sorry that the inspector had to leap aside.\""),
               .cross("You came through at about forty-five, didn't you?", "\"Yes, I know that is too fast. I came in with soft brakes and I did not slow soon enough.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I understand how that appears to the court. I did not mean to endanger anyone.\""),
               .cross("You did not report the brake problem, did you?", "\"No, I wrote a repair note a week before but I did not report it to anyone.\""),
               .cross("You looked back twice before speeding up, didn't you?", "\"I looked in my mirror, as I always do. I did not speed up after I saw the cones.\""),
               .cross("The sign was up when the inspector put it out, wasn't it?", "\"I did not see one. I do not know whether it was there.\"")],
        openings: ("A tractor-trailer driven by {D} came through a closed weigh station lane at about forty-five miles per hour, and an inspector had to leap aside. The camera shows the trailer miss a cone by feet, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a repair note for soft brakes the week before and a ramp sign that was found on the ground the next morning. A driver who cannot stop in time is not one who ignores a closed lane."),
        closings: ("Cones across the lane, a sign at the ramp, and a tractor-trailer at forty-five miles per hour that sent an inspector leaping aside. The video shows all of it, and {D} had been here before.", "Soft brakes, a missing sign, and a driver who stopped, came back, and apologized. The State has not shown that {D} drove in willful disregard of anyone, only that {D} failed to stop in time."),
        timeline: [(-7, "A repair note records soft brakes on {D}'s truck."), (0, "Morning: the inspector sets cones and a sign for the closed lane."), (0, "{D} drives the truck through the closed lane at forty-five and the inspector leaps clear."), (1, "{D} is cited for reckless driving.")],
        identified: "The station camera.",
        mood: .indifferent)

    static let taserMistakeBack = SmallCases.make(
        key: "story.followup.taserMistakeBack",
        category: .publicOrder,
        headlines: ["Woman Wears Old Police Badge at Crash Scene", "Former Officer From Taser Case Charged With Impersonation"],
        law: "impersonatingLEO",
        spec: "Impersonated a law enforcement officer by displaying a badge and directing traffic at a crash scene, on {DATE}.",
        ages: 44...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D}, no longer an officer, stopped at a crash on a county road and wore a badge on {D.his} belt while directing traffic. A deputy arrived and learned {DL} was not employed by any agency. {DL} says {D.he} only helped until help came.",
        state: [E(.video, 3, "Dashcam", "{D} wearing a badge and waving cars past the wreck."), E(.statement, 2, "Motorist", "A motorist says {D} said, 'I'm police, back up.'")],
        defense: [E(.statement, 1, "Helping Out", "{DL} says {D.he} never claimed to be an officer.")],
        role: "Deputy",
        exam: [.direct("What is your assignment?", "\"I am a sheriff's deputy on patrol. I respond to crashes, take reports, and sometimes relieve people who are directing traffic at a scene.\""),
               .direct("What did you find when you arrived at the crash?", "\"A wreck on a county road, with a person in the road waving cars past the wreckage. The person had a badge clipped to a belt and a reflective vest.\""),
               .direct("What did {DL} wear?", "\"A badge on {D.his} belt, and a vest. The badge looked like a law enforcement badge, and anyone passing would have taken it as one.\""),
               .direct("Did you ask whether {DL} was an officer?", "\"I did. {D.He} said {D.he} used to be with an agency but was not employed by one now.\""),
               .direct("What did you confirm about {DL}'s employment?", "\"I called the agency. They said {DL} left the department some time ago and was not on any agency's roster.\""),
               .direct("What did a motorist say?", "\"A motorist said {DL} told them, I'm police, back up. I took the motorist's name and gave it to the detective.\""),
               .direct("What did {DL} say about it?", "\"{D.He} said {D.he} never claimed to be an officer and was only helping until help came.\""),
               .cross("Did {DL} direct traffic until you arrived?", "\"Yes, and {D.he} stopped as soon as I took over. {D.He} did not argue, and {D.he} stepped back to the shoulder without being asked twice.\""),
               .cross("Did {DL} keep the cars safe?", "\"The cars did get past the wreck without hitting anyone or each other. {DL} did a competent job of it, and I said so in my report.\""),
               .cross("Was the badge hidden before the stop?", "\"No, it was on {D.his} belt in plain view of every driver who went by. {D.He} did not try to hide it from me or from anyone.\""),
               .cross("Is it possible the motorist misheard?", "\"It is possible, with sirens and engines running at a scene like that. I did not hear {DL} say it myself, so I only have the motorist's account.\""),
               .cross("You never heard {DL} say the words I'm police, did you?", "\"No, I did not hear them. I arrived after the wreck, and by then {DL} was already waving traffic along.\"")],
        theory: ("{D} posed as a police officer at a crash while wearing a badge and directing traffic.", "{D} was a former officer who stopped to help and wore an old badge out of habit."),
        allocution: "\"I stopped at that crash to keep people safe, and I wore my old badge on my belt out of habit. I only directed traffic until help came. I'm no longer an officer, and I should have taken that badge off. I'm sorry to the deputy and to the people at the scene for any confusion.\"",
        truths: ("{DL} had a prior case in this court as an officer and kept the badge hidden in a drawer.", "A motorist later said {DL} only said, 'I'll help,' and did not mention police."),
        defendant: [.direct("Did you tell anyone you were police?", "\"No, I did not. I said I would help, and I never said I was an officer.\""),
               .direct("Why were you wearing a badge?", "\"It was on my belt from habit. I was an officer for years, and I had forgotten it was clipped there.\""),
               .direct("Why did you stop at the crash?", "\"I wanted to keep people safe. There was a wreck in the road, and cars were coming fast around the curve.\""),
               .direct("What did you do?", "\"I waved cars past the wreck and warned drivers to slow down. I stopped as soon as the deputy arrived.\""),
               .direct("Where do you keep the badge normally?", "\"In a drawer. I took it out that morning for a reason I do not recall.\""),
               .direct("What do you want the deputy to know?", "\"I am sorry for any confusion. I should have taken that badge off, and I should not have gone into the road.\""),
               .cross("You wore an old badge while directing traffic, didn't you?", "\"Yes, and that was wrong of me. I should have taken it off.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, as a former officer, and I know the law better than most. I would not break it on purpose.\""),
               .cross("A motorist says you said I'm police, back up, doesn't that motorist?", "\"I do not recall saying that, and I do not believe I did. What I said was that I would help until the deputies arrived.\""),
               .cross("You are not employed by any agency, are you?", "\"No, I left the department some time ago, and I have not worked for any agency since. I know the badge no longer means what it did.\""),
               .cross("You did not call dispatch before directing traffic, did you?", "\"No, I did not, and I should have. I was thinking only about getting the cars past the wreck before someone was hurt.\"")],
        openings: ("At a crash on a county road, {D}, who is no longer an officer, wore a badge on {D.his} belt and waved cars past the wreck, and a motorist says {D.he} said I'm police, back up. {DL} came before this court in {PRIORDATE} over {PRIOR}, and no agency employs {D.him}.", "The defense will present a former officer who stopped to help keep traffic safe and who never claimed to be an officer. A badge worn from habit, and a helping hand, are not an impersonation."),
        closings: ("A badge on a belt, a vest, and a person waving traffic at a wreck while no agency employed {D}. A motorist says {D} said I'm police, back up, and {D} had been before this court.", "A former officer who stopped to protect people, a badge worn from habit, and a motorist who may have misheard. The State has not shown that {D} claimed to be an officer or meant to deceive anyone."),
        timeline: [(0, "Evening: a crash blocks a county road and {D} stops to help."), (0, "{D} wears a badge on {D.his} belt and waves cars past the wreck."), (0, "A deputy arrives, learns {D} is not employed by any agency, and takes over."), (1, "{D} is charged with impersonating an officer.")],
        identified: "A motorist's call.",
        mood: .divided,
        genders: ["D": .female])

    static let paradeSUVBack = SmallCases.make(
        key: "story.followup.paradeSUVBack",
        category: .family,
        headlines: ["Defendant Violates Protective Order at Ex's Workplace", "SUV Parade Defendant Faces Order Violation Charge"],
        law: "dvpoViolation",
        spec: "Knowingly violated a domestic violence protective order by going to the workplace of {V}, on {DATE}.",
        ages: 36...50,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} walked into the dental office where {V}, {DL}'s former partner, works, though a protective order barred contact. {V}'s boss called deputies. {DL} says {D.he} was only dropping off a child's backpack.",
        state: [E(.video, 3, "Lobby Camera", "{D} walks in and speaks to {V} at the desk."), E(.document, 2, "Protective Order", "An order barring {DL} from {V}'s workplace.")],
        defense: [E(.statement, 1, "Backpack", "{DL} says {D.he} came to hand over a backpack.")],
        role: "Dental office manager",
        exam: [.direct("What is your job at the dental office?", "\"I am the office manager. I supervise the front desk and the staff, and I am responsible for who comes into the lobby and why.\""),
               .direct("What happened that afternoon?", "\"{DL} walked into the lobby and went straight to the front desk, where {V} works. {D.He} spoke to {V} in a low voice, and {V} backed away from the counter.\""),
               .direct("Did you know about the protective order?", "\"Yes, {V} had given me a copy when it was issued. It barred {DL} from contact and from {V}'s workplace, and I kept it in a folder behind the desk.\""),
               .direct("How did {V} react to seeing {DL}?", "\"{V} was shaking and could barely speak. I stepped between them and asked {DL} to leave, and {V} went into the back room.\""),
               .direct("What did the lobby camera show?", "\"It shows {DL} walking in, going to the desk, and speaking to {V} for about two minutes. You can see {V} step back twice.\""),
               .direct("What did {DL} say about why {D.he} was there?", "\"{D.He} said {D.he} was dropping off a child's backpack. I did not see a backpack in {D.his} hands when {D.he} came in.\""),
               .direct("What did you do?", "\"I called deputies and kept {DL} in the lobby until they arrived. {D.He} did not argue or try to leave, and {D.he} sat down in a chair.\""),
               .cross("Was there a backpack in the lobby?", "\"I saw a child's bag on the desk after the deputies came. I do not know who put it there or when.\""),
               .cross("Could {DL} have mailed the backpack or left it with someone else?", "\"Yes, either would have been better. But I understand that {D.he} said the exchange point had been tried first.\""),
               .cross("Did {DL} threaten {V}?", "\"No, I did not hear a threat. {D.He} said something about needing to talk.\""),
               .cross("Did {DL} touch {V} or reach over the desk?", "\"No, {D.he} stayed on the customer side of the counter. {D.He} never touched {V}.\""),
               .cross("You did not hear everything {DL} said, did you?", "\"No, I heard part of it. I heard the words we need to talk and not much else.\"")],
        theory: ("{D} entered {V}'s workplace despite a protective order and spoke to {V} at the desk.", "{D} was a parent who came to return a child's backpack and did not mean to harass {V}."),
        allocution: "\"I walked into that dental office to drop off my child's backpack, and I should not have. I knew about the order, and I should have asked someone else to deliver it. I'm sorry for scaring {V} at work. I'll follow every term of the order from now on.\"",
        truths: ("{DL} had a prior case in this court and said, 'We need to talk,' at the desk.", "A backpack was left in {DL}'s car by the child and {DL} had tried the exchange point first."),
        defendant: [.direct("Did you know about the protective order?", "\"Yes, I knew about it. I should have asked someone else to deliver the backpack, and I did not.\""),
               .direct("Why did you go into the dental office?", "\"To drop off my child's backpack. {V} was the only person who could take it, and I was in a hurry to get to work.\""),
               .direct("Did you try any other way first?", "\"I tried the exchange point first, and nobody was there. I waited ten minutes and then drove to the office.\""),
               .direct("What did you say to {V}?", "\"I said we need to talk. I meant about the backpack and the schedule, but I know how it must have sounded.\""),
               .direct("How long were you in the lobby?", "\"A couple of minutes. I left the bag on the desk and sat down to wait for the deputies, because I knew I was in the wrong.\""),
               .direct("What do you regret?", "\"I am sorry for scaring {V} at work. I will follow every term of the order from now on, even if it means missing a handoff.\""),
               .cross("You walked into a workplace you were barred from, didn't you?", "\"Yes, I did, and I had no right to be there. The order says plainly that I was not to go there.\""),
               .cross("You said we need to talk, didn't you?", "\"Yes, I said it, and I should not have said a word. I should have set the bag down and left.\""),
               .cross("You came before this court in {PRIORDATE} over {PRIOR}, didn't you?", "\"Yes, and I know the order comes out of that case. I understand why it is there.\""),
               .cross("You could have mailed the backpack, couldn't you?", "\"Yes, I could have, and it would have been the smart thing. I did not think it through that morning.\""),
               .cross("The backpack was in your car, wasn't it?", "\"Yes, my child left it in my car after the weekend. I had it with me the whole time.\"")],
        openings: ("A protective order barred {D} from contact with {V} and from {V}'s workplace, yet {D} walked into the dental office lobby and spoke to {V} at the desk. A camera recorded it, {V} was shaking, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a parent who came to return a child's backpack after the exchange point failed. A two-minute visit with no threat and no touching is a mistake, not a defiance of the order."),
        closings: ("The order barred {D} from {V}'s workplace, the camera shows {D} at the desk, and {V} was shaking when the manager stepped in. {D} had been before this court, and the order was served.", "A child's backpack, an exchange point that did not work, and a short visit that ended when deputies came. The State has not shown that {D} meant to violate the order or to frighten {V}."),
        timeline: [(-30, "The protective order against {D} is issued and {V} gives the office manager a copy."), (0, "{D} walks into the dental office lobby and speaks to {V} at the desk."), (0, "The office manager steps between them and calls deputies."), (0, "Deputies arrive and {D} is charged with violating the order.")],
        identified: "The lobby camera.",
        mood: .wantsConviction)

    static let parentsMansionBack = SmallCases.make(
        key: "story.followup.parentsMansionBack",
        category: .whiteCollar,
        headlines: ["Online Tennis Lesson Packages Never Delivered", "Parents' Estate Defendant Faces False Pretenses Charge"],
        law: "falsePretenses",
        spec: "Obtained $2,400 from {V} by falsely representing that tennis lesson packages would be provided, on or about {DATE}.",
        ages: 21...30,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} sold tennis lesson packages online for $2,400 to {V} and never held a lesson. Messages promised a start date that kept moving. {DL} says {D.he} fell ill and planned to refund.",
        state: [E(.digital, 3, "Messages", "{D} promises lessons by Friday three times, then goes silent."), E(.document, 2, "Payment Record", "A $2,400 payment from {V} to {DL}.")],
        defense: [E(.document, 1, "Illness Note", "A clinic note for a week out sick.")],
        role: "Parent who paid",
        exam: [.direct("What were you hoping to buy?", "\"I wanted tennis lessons for my daughter. I found {DL} online, and {D.he} was offering lesson packages at a club near our house.\""),
               .direct("What did you pay for?", "\"$2,400 for a package of lessons. I paid it all in one payment, and I have the payment record and the confirmation.\""),
               .direct("Did any lessons start?", "\"No, they never did. {DL} promised me lessons would start by Friday three different times, and nothing ever happened on any of those Fridays.\""),
               .direct("What did the messages say?", "\"The first one gave a start date. The next two moved it, each time with a reason, and after that {D.he} went silent and stopped answering my texts.\""),
               .direct("What did {DL} say when you pressed for answers?", "\"Much later, {D.he} said {D.he} had been sick and would refund me. I waited, and I never got a refund.\""),
               .direct("How did this affect your family?", "\"It was money we could not easily spare, and my daughter was so disappointed. I felt foolish for paying all of it up front.\""),
               .direct("What did you do next?", "\"I reported it to the sheriff's office with the messages and the payment record. A deputy took my statement and copied the whole thread.\""),
               .cross("Was {DL} actually sick?", "\"{D.He} told me so, but late, after weeks of silence. I did not see any note until the deputies showed me one.\""),
               .cross("Did {DL} offer to refund you?", "\"Yes, in one message, but nothing ever arrived. I checked my account every day for a month.\""),
               .cross("Did {DL} answer your messages at first?", "\"At first, yes, quickly and politely. That is part of why I trusted {D.him} with so much money.\""),
               .cross("You do not know why the lessons never began, do you?", "\"No, I only know what {DL} told me, which kept changing from one message to the next. I never learned the real reason.\""),
               .cross("Did you ever visit the club to check on {DL}?", "\"No, I did not. I should have checked, and I will always wonder if it would have changed things.\"")],
        theory: ("{D} took $2,400 for tennis lessons that were never given.", "{D} fell ill, planned to give lessons, and meant to refund the money."),
        allocution: "\"I sold those tennis lesson packages and then fell ill, and I planned to refund {V}. I spent the money on bills, and I should have repaid it sooner. I know I kept moving the start date. I'm sorry, and I'll refund all twenty-four hundred dollars.\"",
        truths: ("{DL} had a prior case in this court and spent the money on rent and a trip.", "{DL} had $1,200 ready to refund and tried to send it twice."),
        defendant: [.direct("Did you plan to give those lessons?", "\"Yes, I did. I had every intention of starting, and I even reserved a court for the first Friday.\""),
               .direct("What happened to your plans?", "\"I fell ill and was out of work for a week. A clinic note shows that, and I gave it to the deputy.\""),
               .direct("Where is the money now?", "\"It went to bills. I know that was wrong, and I should not have touched it until the lessons were done.\""),
               .direct("Did you try to refund any of it?", "\"I had $1,200 ready and tried to send it twice. Both times it did not go through, and then I stopped trying.\""),
               .direct("Why did you keep moving the start date?", "\"I was embarrassed, and I kept hoping that I would get well enough to start. I should have been honest from the first time.\""),
               .direct("What will you do now?", "\"I will refund all twenty-four hundred dollars. I am sorry to {V} and to the child who was looking forward to lessons.\""),
               .cross("You took $2,400 and never gave a single lesson, didn't you?", "\"Yes, that is true. I wish it were not, and I take responsibility for it.\""),
               .cross("You were before this court in {PRIORDATE} over {PRIOR}, weren't you?", "\"Yes, and I know how that history makes this look. I did not plan to cheat anyone this time.\""),
               .cross("You spent the money on bills, didn't you?", "\"Yes, on rent and other bills. I told myself I would pay it back before anyone noticed.\""),
               .cross("You went silent for weeks, didn't you?", "\"Yes, I did, and it was the worst thing I did in all of this. I was ashamed and I did not know what to say.\""),
               .cross("You never sent the refund, did you?", "\"No, not in full. I tried to send part of it twice, and neither payment cleared.\"")],
        openings: ("{V} paid {D} $2,400 for tennis lesson packages, and no lesson ever took place. The messages promise a start date three times and then go silent, the money was spent on rent and a trip, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a clinic note for a week out sick and two attempts to send a refund. A deal that fell apart because of illness and embarrassment is a broken promise, not a fraud."),
        closings: ("Money paid, three promised Fridays, and then silence. {D} spent the money on bills and a trip and never sent a refund that arrived, and {D} had been here before.", "A plan derailed by illness, a clinic note, and two attempts to refund. The State has not shown that {D} never meant to give the lessons when {D.he} took the money, only that things fell apart."),
        timeline: [(-30, "{V} pays {D} $2,400 for tennis lesson packages for a child."), (-10, "{D} promises lessons by Friday for the first time, and then twice more."), (0, "{V} reports the missing lessons and the lost money to the sheriff's office.")],
        identified: "The payment record.",
        mood: .indifferent)

    static let trailMurdersBack = SmallCases.make(
        key: "story.followup.trailMurdersBack",
        category: .publicOrder,
        headlines: ["Man Charged After Outburst at Library Board Meeting", "Trail Case Defendant Faces Disorderly Conduct Charge"],
        law: "disorderly",
        spec: "Disrupted a public library board meeting by shouting and refusing to leave, on {DATE}.",
        ages: 48...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} stood during a library board meeting, shouted at members, and refused to leave when asked by the chair. A deputy removed {DL} after two warnings. {DL} says {D.he} was speaking during the comment period.",
        state: [E(.video, 3, "Meeting Video", "{D} shouts over the chair and refuses to sit."), E(.statement, 2, "Deputy", "Two warnings given, and {D} stayed.")],
        defense: [E(.document, 1, "Agenda", "The agenda lists a public comment period.")],
        role: "Library board chair",
        exam: [.direct("What is your role on the library board?", "\"I am the chair of the library board. I run the monthly meetings, keep us on the agenda, and make sure that every member of the public who wants to speak gets a turn.\""),
               .direct("What happened at the meeting that evening?", "\"About forty minutes into the meeting, {DL} stood up from the audience and began shouting at the members. {D.He} talked over me when I asked {D.him} to stop.\""),
               .direct("Was there a public comment period?", "\"Yes, early in the meeting, as the agenda says. By the time of the outburst, I had closed it and moved on to the budget item.\""),
               .direct("What did {DL} do after you said the period had ended?", "\"{D.He} kept shouting and would not sit down. I asked {D.him} several times to take a seat and to wait for the next meeting.\""),
               .direct("What did the deputy do?", "\"The deputy gave {DL} two warnings. When {D.he} refused to leave after the second one, the deputy walked {D.him} out of the room.\""),
               .direct("What does the meeting video show?", "\"It shows {DL} standing, shouting over me, and refusing to sit. You can see members covering their ears and the audience turning around.\""),
               .direct("Why did you ask {DL} to leave?", "\"The board could not do its work. Other residents were waiting to hear the budget, and we could not hear each other over {D.him}.\""),
               .cross("Did {DL} wait for the comment period?", "\"I am told {D.he} arrived late and missed it. I do not know for certain, because I did not see {D.him} come in.\""),
               .cross("Did you call the comment period closed in so many words?", "\"I moved to the next agenda item. I may not have said the words closed, and I can see how that could look.\""),
               .cross("Did you speak over {DL} at any point?", "\"Yes, I did, to try to keep order. I raised my voice to be heard.\""),
               .cross("Had {DL} been banned from an earlier meeting?", "\"A letter was sent after the earlier case. I am not sure it covered this meeting.\""),
               .cross("You are not a deputy, so you cannot say what the deputy intended, can you?", "\"No, I cannot. I can only tell you what I said to {DL} and what I heard from where I sat at the head of the table.\"")],
        theory: ("{D} would not stop shouting at a library board meeting and refused to leave.", "{D} was a citizen who tried to speak in a comment period and was talked over."),
        allocution: "\"I raised my voice at that library board meeting because no one would listen during the comment period. I know I refused to leave at first, and I should have walked out after the first warning. I'm sorry to the board and to the audience. I'll speak calmly and keep to my time.\"",
        truths: ("{DL} had a prior case in this court and was banned from a prior meeting by letter.", "The comment period had not been called closed by the chair, who spoke over {DL}."),
        defendant: [.direct("Did you shout at the meeting?", "\"I raised my voice, yes. No one would listen during the comment period, and I felt like I was not being heard.\""),
               .direct("Why did you stand up?", "\"I had waited for the comment period to come to me, and the chair moved on. I stood up to say what I came to say.\""),
               .direct("What did you want to tell the board?", "\"I wanted to complain about the cuts to the children's room. I had notes in my hand, and I never got to read them.\""),
               .direct("Did you hear the chair's warnings?", "\"I heard some of them. I did not leave at first, because I thought I still had a right to speak.\""),
               .direct("What happened when the deputy came?", "\"I left after the second warning. I did not fight or argue with the deputy.\""),
               .direct("What do you regret?", "\"I am sorry to the board and to the audience. I will speak calmly and keep to my time next time.\""),
               .cross("You refused to leave when asked, didn't you?", "\"Yes, at first, and I should have walked out after the first warning. I let my frustration win.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know that history makes this look worse. I wanted to speak, not to cause a scene.\""),
               .cross("Your earlier case led to a letter banning you from meetings, didn't it?", "\"A letter was sent, and I did not think it covered this meeting. I should have asked.\""),
               .cross("The chair had moved on to another agenda item, hadn't the chair?", "\"Yes, the chair had moved on to the budget. I honestly thought the comment period was still open, because nobody said it was over.\""),
               .cross("You shouted over the chair, didn't you?", "\"Yes, I did, and I know it was disruptive to everyone in the room. I should have waited for the chair to finish and then asked again.\"")],
        openings: ("At a library board meeting, {D} stood up, shouted over the chair, and refused to sit or leave after two warnings from a deputy. The meeting video shows it, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present an agenda that lists a public comment period, and a chair who never called it closed. A citizen who raised {D.his} voice to be heard has not disturbed the peace."),
        closings: ("The video shows {D} shouting over the chair, two warnings from a deputy, and a refusal to leave. The comment period was over, and {D} had been banned by letter from an earlier meeting.", "An agenda with a comment period, a chair who talked over a citizen, and a person who left after the second warning. The State has not shown that {D} meant to disrupt the meeting, only to be heard."),
        timeline: [(0, "7 p.m.: the library board meeting begins and the public comment period is held early."), (0, "7:40 p.m.: {D} stands and shouts over the chair and refuses to sit."), (0, "A deputy gives two warnings and walks {D} out."), (1, "{D} is charged with disorderly conduct.")],
        identified: "The meeting video.",
        mood: .divided)

    static let dogMaulingBack = SmallCases.make(
        key: "story.followup.dogMaulingBack",
        category: .publicOrder,
        headlines: ["Puppy Left in Hot Car at Mall Lot", "Dog Owner From Mauling Case Charged With Animal Cruelty"],
        law: "animalCruelty",
        spec: "Intentionally or recklessly deprived an animal of necessary care by leaving a puppy in a closed hot vehicle, on {DATE}.",
        ages: 44...58,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, shoppers saw a puppy panting in {D}'s closed car at a mall lot on a 91-degree afternoon. Security broke a window after 40 minutes. {DL} says {D.he} left the window cracked and was in the store for ten minutes.",
        state: [E(.video, 3, "Security Video", "{D} walks into the mall, and the puppy stays in the car for 40 minutes."), E(.statement, 2, "Vet Note", "The vet notes heat distress and a temperature of 106 degrees.")],
        defense: [E(.statement, 1, "Window Cracked", "{DL} says the window was open an inch.")],
        role: "Mall security guard",
        exam: [.direct("What is your job at the mall?", "\"I am a security guard. I patrol the parking lot and the mall entrances, and I respond when shoppers report something wrong.\""),
               .direct("What did you see that afternoon?", "\"A puppy panting in a closed car in the lot. It was lying on the seat with its tongue out, and its eyes were half shut.\""),
               .direct("What was the weather?", "\"It was a 91-degree afternoon with bright sun overhead. The car was in an open spot with no shade at all, and the pavement was soft from the heat.\""),
               .direct("How long was the puppy in the car?", "\"About forty minutes by the security video. I watched {DL} walk into the mall, and the puppy did not come with {D.him}.\""),
               .direct("Was a window open?", "\"The driver's window was cracked about an inch. That is not enough to help in that heat.\""),
               .direct("What did you do?", "\"After forty minutes with no sign of the owner, I broke the rear window and lifted the puppy out. I carried it into the shade and gave it water.\""),
               .direct("What did the vet say?", "\"The vet's note says the puppy was in heat distress with a temperature of 106 degrees. It recovered, but it was not safe.\""),
               .cross("Was the puppy moving when you got there?", "\"It was barely moving. It lifted its head and then put it down again.\""),
               .cross("Did {DL} come out while you were at the car?", "\"Not right away. {D.He} came out a few minutes after I broke the window.\""),
               .cross("Did {DL} say anything?", "\"{D.He} said {D.he} was only gone for ten minutes. {D.He} said the window was open.\""),
               .cross("Did the receipt show the time in the store?", "\"I have seen a receipt that shows a purchase lasting about ten minutes. It does not show where {DL} went after that, and the video does not either.\""),
               .cross("You did not see {DL} leave the car, did you?", "\"No, I saw {D.him} walk in on the video. I did not see {D.him} park.\"")],
        theory: ("{D} left a puppy in a hot car for forty minutes.", "{D} left the window cracked and meant to be gone only ten minutes."),
        allocution: "\"I was in the store for about ten minutes, and I left the window cracked, and I didn't think the puppy was in danger. I now see how hot it was that afternoon. I'm sorry for the puppy's distress and for the broken window. I'll never leave an animal in a car again.\"",
        truths: ("{DL} had a prior case in this court over dogs and received a warning that day to bring water.", "The puppy recovered and {DL} was in the store ten minutes, as a receipt shows."),
        defendant: [.direct("How long were you in the store?", "\"About ten minutes. I made a purchase and I have the receipt with the time on it.\""),
               .direct("Why was the puppy in the car?", "\"I had just picked it up and was running errands. I meant to be quick.\""),
               .direct("Did you leave the window open?", "\"Yes, I cracked it an inch. I thought that would be enough for a short trip.\""),
               .direct("Did you think the puppy was in danger?", "\"No. I did not think it was that hot, and I did not check the temperature.\""),
               .direct("What happened after the store?", "\"I stopped at a kiosk and lost track of time. When I came out, security was at my car.\""),
               .direct("What do you regret?", "\"I am sorry for the puppy's distress and for the broken window. I will never leave an animal in a car again.\""),
               .cross("It was 91 degrees, wasn't it?", "\"Yes, it was, and I did not think about it as I should have. I treated it like any spring day and I was wrong.\""),
               .cross("You did not check the temperature in the car, did you?", "\"No, I did not check it before I went in or when I came back. I trusted that a cracked window would be enough.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I had been warned in that case to bring water for the dog when I went out. I should have listened to that warning.\""),
               .cross("You were gone about forty minutes, weren't you?", "\"The video says so, and I will not argue with it. It felt like less, but I know the camera does not lose track of time.\""),
               .cross("You never went back to check on the puppy, did you?", "\"No, I did not, and that is the part I regret most. I should have walked out to the car at least once.\"")],
        openings: ("On a 91-degree afternoon, security found a puppy panting in {D}'s closed car at a mall lot, and the video shows {D} inside the mall for forty minutes. A vet recorded heat distress and a temperature of 106 degrees, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a window cracked an inch and a receipt that shows a ten-minute stop in the store. A short trip that ran long is carelessness, and the State must prove cruelty."),
        closings: ("A puppy in a closed car for forty minutes, a vet's note of 106 degrees, and a window that was cracked only an inch. {D} had been warned about dogs before and had been before this court.", "A short trip, a cracked window, and a receipt for ten minutes in the store. The State has not shown that {D} meant to hurt the puppy, only that {D.he} lost track of the time."),
        timeline: [(0, "2 p.m.: {D} parks at the mall and leaves a puppy in the car with the window cracked."), (0, "2:40 p.m.: security sees the puppy panting and breaks a window."), (0, "A vet records heat distress and a temperature of 106 degrees."), (1, "{D} is charged with animal cruelty.")],
        identified: "Mall security video.",
        mood: .wantsConviction)

    static let cityStranglerBack = SmallCases.make(
        key: "story.followup.cityStranglerBack",
        category: .cyber,
        headlines: ["Repeated Messages to Former Coworker Lead to Stalking Complaint", "Restaurant Manager Case Defendant Faces Cyberstalking Charge"],
        law: "cyberstalking",
        spec: "Repeatedly sent electronic messages to {V} with intent to torment, after being told to stop, on or about {DATE}.",
        ages: 28...38,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} sent {V}, a former coworker, 63 messages in nine days after {V} had said to stop. The messages said {DL} was watching {V}'s street. {DL} says the messages were friendly and a misunderstanding.",
        state: [E(.digital, 3, "Message Log", "63 messages in nine days, after a request to stop."), E(.document, 2, "Stop Request", "{V}'s written message asking {DL} to stop.")],
        defense: [E(.statement, 1, "Friendly", "{DL} says the tone was friendly.")],
        role: "Former coworker",
        exam: [.direct("How do you know {DL}?", "\"{DL} used to be a coworker of mine. We worked in the same office for about two years, and we were friendly but never close friends.\""),
               .direct("What did {DL} send you?", "\"Sixty-three messages in nine days. They came by text, by email, and through a messaging app, at all hours of the day and night.\""),
               .direct("Did you ask {DL} to stop?", "\"Yes, after the first few days I sent a written message asking {D.him} to stop contacting me. I wrote it plainly so there would be no mistake about what I meant.\""),
               .direct("What did {DL} do after that?", "\"{D.He} kept messaging me. Some of the messages sounded friendly at first, and then they changed and said {D.he} was watching my street.\""),
               .direct("What exactly did the messages say about your street?", "\"They said {DL} was watching my street. One said {D.he} could see my porch light from where {D.he} was.\""),
               .direct("How did that make you feel?", "\"Terrified. I live alone, and I did not know whether {D.he} was nearby. I checked every window and door before I went to bed.\""),
               .cross("Were some of the messages friendly in tone?", "\"Some started that way, yes, and I understand why {D.he} might see it as friendly. After I asked {D.him} to stop, none of them were welcome.\""),
               .cross("Did {DL} ever come to your home that you saw?", "\"I do not know whether {D.he} drove by, and I never saw {D.him} on my street.\""),
               .cross("Did {DL} threaten you directly in any message?", "\"Not in so many words. The messages about watching my street scared me more than any direct threat could have.\""),
               .cross("Did {DL} apologize at the end?", "\"Near the end {D.he} sent a message that said sorry, and I did not reply to it. By then I did not trust anything {D.he} said.\""),
               .cross("You do not know where {DL} was when the messages were sent, do you?", "\"No, I do not know. I know only what the messages said and what I felt when I read them.\"")],
        theory: ("{D} kept messaging {V} sixty-three times after being told to stop, and said {D.he} was watching {V}'s street.", "{D} sent friendly messages and misunderstood a request to stop."),
        allocution: "\"I sent those messages because I wanted to reconnect, and I thought they were friendly. I know {V} asked me to stop, and I kept going a few times. I'm sorry for how they came across. I never meant to frighten {V.him}, and I'll leave {V.him} alone.\"",
        truths: ("{DL} had a prior case in this court and drove past {V}'s street twice.", "{DL} deleted the last messages and apologized, though {V} had not replied."),
        defendant: [.direct("Did you send those messages?", "\"Yes, I did. I wanted to reconnect with a former coworker, and I thought it would be welcome.\""),
               .direct("Why did you keep going after {V} asked you to stop?", "\"A few times I did not read the request carefully. I thought it was a misunderstanding and that {V} would be glad to hear from me.\""),
               .direct("Did you mean to frighten {V}?", "\"No, I never meant to frighten {V.him}. I thought the messages were friendly and that nobody would take them badly.\""),
               .direct("What did you mean by watching your street?", "\"It was a figure of speech. I meant that I knew where {V} lived from an old holiday party at the office.\""),
               .direct("What did you do at the end?", "\"I deleted the last messages and sent an apology. {V} did not reply, and I understood.\""),
               .direct("What will you do now?", "\"I will leave {V.him} alone completely. I am sorry for how the messages came across.\""),
               .cross("You sent sixty-three messages in nine days, didn't you?", "\"Yes, that is what the log says, and I did not count them as I sent them. It is more than I thought.\""),
               .cross("You came before this court in {PRIORDATE} over {PRIOR}, didn't you?", "\"Yes, and I know that history makes this look worse. I should have taken more care after that case.\""),
               .cross("You drove past {V}'s street twice, didn't you?", "\"I may have gone that way, because it is on a route I take. I never stopped or got out of my car.\""),
               .cross("You continued after the written request to stop, didn't you?", "\"Yes, a few times, and I know that was wrong. I should have taken the hint immediately.\""),
               .cross("You deleted the last messages, didn't you?", "\"Yes, I did, to show I was sorry. I know it may look like I was hiding something, but I was not.\"")],
        openings: ("Over nine days, {D} sent {V}, a former coworker, sixty-three messages after {V} asked in writing for them to stop. Some said {D.he} was watching {V}'s street, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present messages that began as friendly check-ins and a person who apologized and deleted the last ones. A misread tone and an old holiday party are not stalking."),
        closings: ("Sixty-three messages after a written request to stop, some saying {D} was watching {V}'s street, sent to a person who lives alone. {D} had been before this court on a similar charge.", "Friendly messages, a misunderstanding, and an apology at the end. The State has not shown that {D} meant to frighten {V}, only that {D} did not take the hint soon enough."),
        timeline: [(-9, "{D} begins messaging {V}, a former coworker."), (-5, "{V} asks {D} in writing to stop."), (0, "{V} reports sixty-three messages to the sheriff's office.")],
        identified: "The message log.",
        mood: .wantsConviction)

    static let hazingDeathBack = SmallCases.make(
        key: "story.followup.hazingDeathBack",
        category: .violent,
        headlines: ["Student Punches Man in Bar Lot After Football Game", "Fraternity Case Defendant Faces Assault Charge"],
        law: "simpleAssault",
        spec: "Assaulted {V} by punching {V.him} in the face, on {DATE}.",
        ages: 20...30,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} punched {V} outside a bar after a football game in a dispute over a parking spot. {V}'s lip was split. {DL} says {V} lunged first.",
        state: [E(.video, 3, "Bar Camera", "{D} swings and {V} falls back, holding {V.his} lip."), E(.physical, 2, "Photo", "A split lip, photographed by deputies.")],
        defense: [E(.statement, 1, "Lunge", "{DL} says {V} lunged.")],
        role: "Bar bouncer",
        exam: [.direct("What is your job at the bar?", "\"I work the door as a bouncer. I check identification, watch the sidewalk, and step in when a night is about to turn into a fight.\""),
               .direct("What was the night like?", "\"It was after a football game, and the place was crowded. People were spilling out onto the sidewalk and the parking lot across the street.\""),
               .direct("What did you see between {DL} and {V}?", "\"They were arguing over a parking spot near the lot entrance. Both of them were loud, and both of them had been drinking.\""),
               .direct("Who started the argument?", "\"It was words from both of them. I could not tell you who said the first one, because it started before I walked over.\""),
               .direct("What happened next?", "\"{DL} swung at {V} and landed a punch on the face. {V} fell back holding {V.his} lip, and I stepped in between them.\""),
               .direct("What does the bar camera show?", "\"It shows {DL} swinging and {V} stumbling back with a hand on {V.his} mouth. It does not show clearly what happened in the seconds before the punch.\""),
               .direct("What did you do afterward?", "\"I held {DL} back from {V} and called deputies. A deputy photographed the split lip and took statements from both.\""),
               .cross("Did {V} lunge at {DL} first?", "\"I am not sure. I saw {V} step forward just before the swing, but I could not tell whether it was a lunge or a step.\""),
               .cross("Did {V} grab {DL}'s shirt?", "\"A friend of {V}'s says so. I did not see it, because my view was blocked by a truck.\""),
               .cross("Was {DL} calm before the punch?", "\"{D.He} was loud, but no louder than {V}. I have seen a lot worse on a night like that.\""),
               .cross("Did {DL} try to leave the scene?", "\"No, {D.he} stayed, and {D.he} helped me hold the door while we waited for the deputies.\""),
               .cross("You did not see who stepped forward first, did you?", "\"No, I did not. I saw both of them close together, and then the punch.\"")],
        theory: ("{D} punched {V} over a parking spot outside a bar.", "{D} punched {V.him} once after {V.he} grabbed {D.his} shirt."),
        allocution: "\"We argued outside the bar over a parking spot, and {V} grabbed me, and I punched {V.him} once. I'm sorry that {V.his} lip was split. We'd both had a long night, and I should have stepped away. I'll pay for the medical bill.\"",
        truths: ("{DL} had a prior case in this court and stepped forward first.", "{V} grabbed {DL}'s shirt before the swing, and a friend saw it."),
        defendant: [.direct("Did you punch {V}?", "\"Yes, I did, once. I did not mean to hurt {V.him}, but I know I did.\""),
               .direct("Why did you punch {V.him}?", "\"{V} grabbed my shirt and came toward me. I was afraid, and I swung before I thought.\""),
               .direct("What was the argument about?", "\"A parking spot near the lot entrance. I had been waiting for it, and {V} pulled in ahead of me.\""),
               .direct("Did you step toward {V}?", "\"A little. I walked over to talk, and I should have stayed at my car.\""),
               .direct("Had you been drinking?", "\"I had a couple of beers during the game. I was not drunk, but I was loose.\""),
               .direct("What do you regret?", "\"I am sorry that {V.his} lip was split. We had both had a long night, and I should have stepped away. I will pay for the medical bill.\""),
               .cross("You swung at {V}, didn't you?", "\"Yes, I swung, and the video shows it. I will not argue with the camera.\""),
               .cross("You stepped forward first, didn't you?", "\"I walked toward {V} to talk. I did not mean it as a challenge, but I understand how it looked.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know that history looks bad here. I did not go out looking for a fight that night.\""),
               .cross("{V} did not hit you first, did {V.he}?", "\"No, {V.he} did not hit me. {V.He} grabbed my shirt and pulled, and that is what made me throw the punch.\""),
               .cross("A split lip is a real injury, isn't it?", "\"Yes, it is, and I know I caused it. I am sorry for that, and I will pay whatever the doctor charged.\"")],
        openings: ("After a football game, {D} and {V} argued over a parking spot outside a bar, and {D} punched {V}, splitting {V.his} lip. A bar camera recorded the swing, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a grabbed shirt and a friend who saw it happen. A single punch thrown after being grabbed is self-defense, and the State must prove that it was not."),
        closings: ("The camera shows {D} swinging and {V} falling back with a split lip. {D} stepped forward first, and {D} had been in this court before over a fight.", "A grab on the shirt, a friend who saw it, and one punch that ended the fight. The State has not shown that {D} was the aggressor, and {D} has offered to pay the medical bill."),
        timeline: [(0, "10 p.m.: {D} and {V} argue over a parking spot outside the bar."), (0, "10:05 p.m.: {D} punches {V} and a bar camera records it."), (0, "A deputy photographs {V}'s split lip and takes statements."), (1, "{D} is charged with assault.")],
        identified: "The bar camera.",
        mood: .divided)

    static let hurricaneFraudBack = SmallCases.make(
        key: "story.followup.hurricaneFraudBack",
        category: .whiteCollar,
        headlines: ["Driveway Sealing Deposits Taken, Work Never Done", "Hurricane Contractor Faces New False Pretenses Charge"],
        law: "falsePretenses",
        spec: "Obtained $3,200 from {V} by falsely representing that a driveway would be resurfaced, on or about {DATE}.",
        ages: 36...58,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} took $3,200 from {V} to resurface a driveway and never showed up. A flyer listed a business license number that belonged to another company. {DL} says rain delayed the work and a partner left.",
        state: [E(.document, 3, "Flyer", "A flyer with a license number that belongs to another company."), E(.digital, 2, "Payment App", "{V} paid $3,200 to {DL}.")],
        defense: [E(.statement, 1, "Rain Delay", "{DL} says weather held up the job.")],
        role: "Homeowner",
        exam: [.direct("What did you hire {DL} to do?", "\"I hired {DL} to resurface my driveway. It was cracked from the last storm season, and I wanted it repaired properly before winter set in.\""),
               .direct("What did you pay?", "\"$3,200, sent through a payment app on the day we agreed on the job. I still have the confirmation and a screenshot of the transfer.\""),
               .direct("Did any work ever start?", "\"Not one day. {DL} never showed up, and no crew, truck, or equipment ever came to my house, and nobody called to explain.\""),
               .direct("What did the flyer say?", "\"It listed a business name and a license number. I checked the number later, and it belongs to a different company altogether.\""),
               .direct("What did {DL} tell you when you called?", "\"At first {D.he} said rain had delayed the job. Later {D.he} said a partner had left and the work would have to be rescheduled.\""),
               .direct("How has this affected you?", "\"I had to pay a second contractor to do the job, and it cost more. I lost the whole $3,200 and a season of use of my own driveway.\""),
               .direct("What did you do next?", "\"I reported it to the sheriff's office with the flyer, the messages, and the payment record. A deputy copied everything that same week.\""),
               .cross("Was there rain during that period?", "\"A little, on a couple of days. Most of the days were dry, and my neighbor had paving done the same week.\""),
               .cross("Did {DL} offer to refund you?", "\"By message, yes, in a short note. Nothing ever arrived, and I did not receive any amount at all.\""),
               .cross("Did {DL} mention a partner before you paid?", "\"No, never. The partner came up only after I started calling and asking where the crew was.\""),
               .cross("Did you check the license number before you paid?", "\"No, I trusted the flyer because it looked professional. I should have checked, and I did not.\""),
               .cross("You do not know what {DL} did with the money, do you?", "\"No, I do not. I know only that it went to {D.him} and that I never saw a day of work for it.\"")],
        theory: ("{D} took $3,200 for a driveway job and never showed up to do it.", "{D} meant to do the job and was delayed by weather and a partner who left."),
        allocution: "\"I took that money to resurface the driveway, and I spent it on supplies. Rain delayed the work, and my partner left, and I borrowed to cover other costs. I should have said so to {V}. I'm sorry, and I'll refund every dollar of the three thousand two hundred.\"",
        truths: ("{DL} had a prior case in this court and took deposits from three other homeowners.", "A partner did leave and {DL} offered a refund by message."),
        defendant: [.direct("Did you plan to do the job?", "\"Yes, I did. I bought some of the supplies and I gave {V} a date to start, and I meant to keep it.\""),
               .direct("Where did the money go?", "\"To supplies and to other costs I was behind on. I borrowed against the job to cover a bill, and I fell further behind.\""),
               .direct("Why did the work not happen?", "\"Rain delayed the start, and then my partner left. I was stuck with a job I could not do alone and I did not know how to say so.\""),
               .direct("Whose license number was on the flyer?", "\"It belonged to my former partner's company. I borrowed the number, and I should not have put it on a flyer.\""),
               .direct("Did you tell {V} about the problems?", "\"Not as soon as I should have. I was embarrassed, and I kept hoping I could fix it before {V.he} found out.\""),
               .direct("What will you do now?", "\"I will refund every dollar of the three thousand two hundred. I am sorry to {V.him}, and I know I should have called.\""),
               .cross("You took $3,200 and did no work at all, didn't you?", "\"That is true, and I do not dispute it. I took the money and I did not finish the job, and I am sorry for it.\""),
               .cross("You were before this court in {PRIORDATE} over {PRIOR}, weren't you?", "\"Yes, and I know that history makes this look like a pattern. I did not plan to cheat {V} when I took the money.\""),
               .cross("The license number on the flyer belonged to another company, didn't it?", "\"Yes, it did. I should not have used it, and I understand why that makes the flyer look false.\""),
               .cross("You took deposits from other homeowners as well, didn't you?", "\"I took a few others, and I did not complete those either. That is part of why I fell behind and could not do any of them.\""),
               .cross("You offered a refund by message, but never paid one, correct?", "\"Yes, I offered it and did not pay it. I did not have the money at that time, and I should have said so plainly.\"")],
        openings: ("{V} paid {D} $3,200 to resurface a driveway, and no work was ever done. The flyer carries a license number that belongs to another company, other homeowners say the same thing happened to them, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present rain, a partner who left, and an offer to refund. A job that fell apart because of weather and a partner is a business failure, not a lie told at the start."),
        closings: ("A flyer with another company's license, $3,200 paid, and not one day of work. Three other homeowners were taken the same way, and {D} had been before this court on a similar charge.", "Rain, a partner who quit, and a refund offered by message. The State has not shown that {D} never meant to do the job when {D.he} took the money, only that the job failed."),
        timeline: [(-30, "{V} pays {D} $3,200 to resurface the driveway."), (-10, "The promised start date passes and no one shows up."), (0, "{V} learns the flyer's license number belongs to another company and reports it to the sheriff's office.")],
        identified: "The payment app record.",
        mood: .wantsConviction)

    static let fakeDoctorBack = SmallCases.make(
        key: "story.followup.fakeDoctorBack",
        category: .whiteCollar,
        headlines: ["Vitamin Injection Packages Sold From Van", "Unlicensed Clinic Owner Faces New Fraud Charge"],
        law: "falsePretenses",
        spec: "Obtained $2,800 from {V} by falsely representing that licensed vitamin injection packages would be given, on or about {DATE}.",
        ages: 38...58,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} sold 'vitamin injection' packages from a van outside a gym for $2,800. {V} got one injection from an assistant who did not wear gloves, and then nothing. {DL} says the injections were legal and the assistant quit.",
        state: [E(.document, 3, "Contract", "A contract promising 12 licensed injections for $2,800."), E(.statement, 2, "Assistant", "The assistant says none was licensed.")],
        defense: [E(.document, 1, "Supplier Invoice", "An invoice for vitamins and syringes.")],
        role: "Customer",
        exam: [.direct("What did you buy from {DL}?", "\"A package of twelve vitamin injections for $2,800. {D.He} sold it from a van parked outside my gym, and the contract said the injections were licensed.\""),
               .direct("How did the sale happen?", "\"{DL} stopped me as I was leaving the gym and said {D.he} offered licensed vitamin injections that would boost my energy. {D.He} showed me a binder with before and after photos.\""),
               .direct("What does the contract say?", "\"It promises twelve licensed injections for $2,800 over three months. I signed it in the van and paid by card.\""),
               .direct("How many injections did you get?", "\"One. An assistant gave it to me right there in the van, and the assistant was not wearing gloves.\""),
               .direct("What happened after that?", "\"Nothing. The second appointment never happened, the phone number stopped working, and the van was gone from outside the gym.\""),
               .direct("What did the assistant tell you?", "\"Later the assistant told me none of the injections was licensed. The assistant said {D.he} had quit because of it.\""),
               .direct("How has this affected you?", "\"I lost $2,800 and I was frightened about what I had been injected with. I spent a week getting checked by my own doctor.\""),
               .cross("{DL} says the injections were legal, doesn't {D.he}?", "\"That is what {D.he} says, and I cannot prove what was in the syringe. I know only what the contract promised and what I was told.\""),
               .cross("Was there an invoice for supplies?", "\"I have seen an invoice for vitamins and syringes. It does not show a license.\""),
               .cross("Did anyone else give you an injection?", "\"No, only the assistant, and only once, in the van, while {DL} stood by with the contract. Nobody else ever came to my appointments.\""),
               .cross("Did you get sick from the injection?", "\"I was sore for a day, and then fine. My doctor found nothing wrong.\""),
               .cross("You do not know who the supplier was, do you?", "\"No, I do not. I know only what the invoice says.\"")],
        theory: ("{D} sold packages of licensed injections that were not licensed and stopped after one.", "{D} ran a legal vitamin business that lost its assistant."),
        allocution: "\"I sold those vitamin injection packages, and I believed they were legal. The assistant gave one injection and then quit, and I did not know about the gloves. I'm sorry to {V} for what happened. I'll refund the twenty-eight hundred dollars and stop selling anything I can't verify.\"",
        truths: ("{DL} had a prior case in this court for an unlicensed clinic and was never licensed.", "The supplier invoice shows real vitamins and {DL} offered a refund."),
        defendant: [.direct("Were you licensed to give injections?", "\"I was not, but the assistant I hired was licensed, as far as I knew. I relied on that, and I had no reason to doubt it when I hired the assistant.\""),
               .direct("Did you give any of the injections yourself?", "\"No, the one that {V} got was given by my assistant while I was in the van doing the paperwork. I never put a needle into anyone myself.\""),
               .direct("Were those injections real vitamins?", "\"Yes, and I have the supplier's invoice for vitamins and syringes. It shows exactly what I bought and from whom, and the dates match the sale.\""),
               .direct("Why did the service stop after one injection?", "\"The assistant quit, and I could not find another one fast enough. I did not tell {V} the whole truth about that, and I should have called right away.\""),
               .direct("What do you say about the gloves?", "\"I did not know about it until {V} told the deputies. I would never have allowed it, and I am sorry that it happened in my van.\""),
               .direct("What will you do now?", "\"I will refund the twenty-eight hundred dollars in full. I will also stop selling anything that I cannot verify and have checked by a doctor.\""),
               .cross("You sold a package of twelve injections and delivered only one, didn't you?", "\"Yes, that is true, and I do not dispute it. The rest were supposed to come once I found someone to replace the assistant.\""),
               .cross("You came before this court in {PRIORDATE} over {PRIOR}, didn't you?", "\"Yes, and I know how this looks beside that case. I did not set out to cheat anyone, but I see why it seems that way.\""),
               .cross("You were never licensed to give injections yourself, were you?", "\"No, I was not licensed. I hired a person I believed was, and I never checked the assistant's papers myself.\""),
               .cross("The contract said licensed injections, didn't it?", "\"Yes, it did, and I wrote that because I believed the assistant held a license. I did not know that was untrue.\""),
               .cross("You offered a refund but never paid one, correct?", "\"Yes, that is correct. I did not have the money available when I offered it, and I should have said so plainly.\"")],
        openings: ("{V} paid {D} $2,800 for twelve licensed vitamin injections sold from a van outside a gym, got one injection from an assistant who wore no gloves, and then nothing. {DL} came before this court in {PRIORDATE} over {PRIOR}, and the assistant says none was licensed.", "The defense will present a supplier invoice for real vitamins and syringes and a business that lost its assistant. A business that failed is not the same as a fraud."),
        closings: ("A contract promising licensed injections, one given without gloves, and eleven never given. {D} was never licensed and had been before this court on a similar charge.", "A real supplier, a real invoice, and an assistant who quit. The State has not shown that {D} meant to cheat {V}, only that the business fell apart and the money was not returned."),
        timeline: [(-14, "{V} signs the contract and pays $2,800 in the van outside the gym."), (-7, "An assistant gives {V} one injection without gloves."), (0, "{V} reports the missing injections and the cost to the sheriff's office.")],
        identified: "The contract in the customer's hands.",
        mood: .wantsConviction)

    static let daycareCamerasBack = SmallCases.make(
        key: "story.followup.daycareCamerasBack",
        category: .violent,
        headlines: ["Teacher at Dance Studio Charged After Grabbing Child's Arm", "Daycare Teacher Case Defendant Faces Child Abuse Charge"],
        law: "childAbuseMisd",
        spec: "Inflicted physical injury on a child by grabbing the child's arm and bruising it at a dance studio, on {DATE}.",
        ages: 23...43,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D}, now an assistant at a dance studio, grabbed a 6-year-old by the arm and pulled the child across a room during a class. A parent saw bruises that night. {DL} says the child was running toward a door and the grab was to keep the child safe.",
        state: [E(.video, 3, "Studio Camera", "{D} grabs a child's arm and pulls across the floor."), E(.physical, 2, "Bruise Photo", "Finger-shaped bruises on the child's arm.")],
        defense: [E(.statement, 1, "Door", "{DL} says the child was running toward an exit.")],
        role: "Studio owner",
        exam: [.direct("What is your connection to the dance studio?", "\"I own the studio. I teach several classes myself, and I hire assistants to help with the younger groups, including the six-year-olds' class on weeknights.\""),
               .direct("What does your studio camera show?", "\"It shows {DL}, one of my assistants, grabbing a six-year-old child by the arm and pulling the child across the floor. It is clear, and it lasts a few seconds.\""),
               .direct("What was happening in the class at that moment?", "\"The children were lining up to start a warm-up. One child had wandered toward the side of the room, and {DL} went over and took hold of the arm.\""),
               .direct("Did you see the child afterward?", "\"Yes, the child was crying and held that arm against the chest. I took the child to the front desk and called the parent.\""),
               .direct("What did the parent report?", "\"The parent called that night and sent a photo of finger-shaped bruises on the child's arm. That photo is in the file.\""),
               .direct("How did {DL} explain it?", "\"{D.He} said the child was running toward an exit and the grab was to keep the child safe. {D.He} said {D.he} shouted first.\""),
               .direct("Had {DL} been told anything about handling children?", "\"Yes, I told {D.him} when I hired {D.him} that staff must keep their hands off the children. {D.He} signed the staff rules, and the rules say that.\""),
               .cross("Was the child near a door?", "\"Near, yes. There is a side exit about ten feet from where the child was standing.\""),
               .cross("Where does that door lead?", "\"To the parking lot, which is busy at that hour with parents arriving.\""),
               .cross("Did {DL} shout a warning before grabbing?", "\"I did not hear it on the video, because the camera has no sound. {D.He} says {D.he} did.\""),
               .cross("Could the grip have been lighter than it looks?", "\"The angle hides the hand, so I cannot say. The bruises suggest it was firm.\""),
               .cross("You were not in the room when it happened, were you?", "\"No, I was in the office. I saw it afterward on the camera.\"")],
        theory: ("{D} grabbed a six-year-old hard enough to bruise during a dance class.", "{D} grabbed the child to keep the child from running out a door to a busy lot."),
        allocution: "\"I grabbed that child by the arm because {V.he} was running toward the door, and I wanted to keep the child safe. I shouted, and I know it was too hard. I'm so sorry about the bruise. I love teaching dance, and I'll learn better ways to guide children.\"",
        truths: ("{DL} had a prior case in this court for a daycare and was told to keep hands off.", "The door led to a busy lot, and {DL} used a light grip, as the video angle hides."),
        defendant: [.direct("Did you grab the child's arm?", "\"Yes. I wanted to keep the child from running into the parking lot, and I took hold of the arm to stop it.\""),
               .direct("Why did you think the child was in danger?", "\"The child was running toward the side door, which opens to a busy lot. I was afraid a car would be pulling in.\""),
               .direct("Did you ask the child to stop first?", "\"I shouted for the child to stop. The music was on and the child did not hear me, so I reached out.\""),
               .direct("How hard did you grip?", "\"I thought it was a light grip. I know now that it was too hard, and I am so sorry about the bruise.\""),
               .direct("Why were you working with children?", "\"I love teaching dance. I have been an assistant for two years, and I try to be kind to every child.\""),
               .direct("What will you do differently?", "\"I will learn better ways to guide children without touching them. I will use my voice and stand in front of a door instead.\""),
               .cross("The video shows you pulling the child across the floor, doesn't it?", "\"Yes, I pulled the child several steps. I was moving fast, and I did not think about how hard I was holding on.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I was told in that case to keep my hands off children. I should have remembered it.\""),
               .cross("Finger-shaped bruises were photographed on the arm, weren't they?", "\"Yes, and I have seen the photo. It makes me sick to look at it.\""),
               .cross("The studio rules say staff must not touch the children, don't they?", "\"Yes, and I signed them. I should have stepped in front of the door instead.\""),
               .cross("You did not tell the owner about the grab, did you?", "\"No, I did not, and I regret that. I was afraid, and I thought it was minor.\"")],
        openings: ("A studio camera shows {D}, an assistant at a dance studio, grabbing a six-year-old by the arm and pulling the child across the floor. A parent photographed finger-shaped bruises that night, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a child who was running toward a door to a busy parking lot, and an assistant who took hold of an arm to keep the child safe. A grip that was too hard is a mistake, not an abuse."),
        closings: ("The video shows a child pulled by the arm, the photo shows finger-shaped bruises, and the studio rules said hands off. {D} had been here before for the same kind of thing.", "A child running toward a door, a busy lot beyond it, and an assistant who acted in a second. The State has not shown that {D} meant to hurt the child, only that {D.he} gripped too hard."),
        timeline: [(0, "Evening: the six-year-olds' dance class begins and the children line up for a warm-up."), (0, "{D} grabs a child by the arm and pulls the child across the floor, and the studio camera records it."), (0, "The studio owner calls the parent, who photographs bruises on the child's arm that night."), (1, "The parent calls deputies and {D} is charged.")],
        identified: "The studio camera.",
        mood: .divided,
        genders: ["D": .female])

    static let feedStoreFireBack = SmallCases.make(
        key: "story.followup.feedStoreFireBack",
        category: .whiteCollar,
        headlines: ["Farmer Claims Stolen Tractor Attachments Never Existed", "Feed Store Fire Defendant Faces Insurance Fraud Charge"],
        law: "insuranceFraud",
        spec: "Presented a false claim to an insurer for stolen equipment valued at $14,000, on or about {DATE}.",
        ages: 45...66,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} reported a barn break-in and filed a $14,000 claim for stolen tractor attachments. An adjuster found sales receipts for the same attachments sold the month before. {DL} says the sale paper was for old parts.",
        state: [E(.document, 3, "Sale Receipts", "Receipts showing the attachments were sold to a dealer a month earlier."), E(.statement, 2, "Adjuster", "The adjuster found no sign of a forced entry on the barn.")],
        defense: [E(.document, 1, "Old Parts", "A list of old parts, not the claimed ones.")],
        role: "Insurance adjuster",
        exam: [.direct("What is your job?", "\"I am a claims adjuster for a farm insurance company. I investigate losses on barns, equipment, and crops, and I decide whether a claim matches what I find on the property.\""),
               .direct("What did {DL} claim?", "\"A break-in at a barn, and stolen tractor attachments worth $14,000. The claim form lists a loader, a tiller, and a few other attachments by serial number.\""),
               .direct("What did you find at the barn?", "\"The doors and latches showed no sign of a forced entry. One latch was loose, but it had not been pried or cut.\""),
               .direct("What did your search of sales records turn up?", "\"Sales receipts showing the attachments had been sold to an equipment dealer a month before the report. The dealer's paperwork is in the file.\""),
               .direct("Were the serial numbers on the receipts the same as on the claim?", "\"Some were. Others were not the same, and I cannot say that every attachment on the claim was sold.\""),
               .direct("What did {DL} say about the receipts?", "\"{D.He} said the sale paper was for old parts that {D.he} had already sold. {D.He} said the attachments on the claim were different ones.\""),
               .direct("Why does this matter to the company?", "\"A false claim raises costs for every honest farmer. We investigate every large claim, and this one did not add up.\""),
               .cross("Were old parts sold to the dealer?", "\"Some, but not the same serials. The dealer says the sold parts were old and different.\""),
               .cross("Was the latch on the barn loose?", "\"Yes. I cannot say whether it was loose before or after a break-in.\""),
               .cross("Did you find any other sign of theft?", "\"No broken glass and no pry marks. I found some tire tracks, but they could be anyone's.\""),
               .cross("Did {DL} cooperate?", "\"Yes, {D.he} gave me every record I asked for. {D.He} did not hide the sale.\""),
               .cross("You cannot say which attachments were taken, if any, can you?", "\"No, I cannot. I can tell you only what the receipts and the barn show.\"")],
        theory: ("{D} claimed $14,000 for attachments that had already been sold.", "{D} reported a break-in and claimed attachments, mixing up old parts that had been sold."),
        allocution: "\"The latch on that barn was loose, and I reported the break-in as I found it. The sales paper was for old parts that I had already sold. I understand how the receipts look. I'm sorry for the confusion to the adjuster, and I'll help sort out which attachments were taken.\"",
        truths: ("{DL} had a prior case in this court over a store fire and needed money after a failed harvest.", "The dealer confirms the sold parts were old and not the claimed attachments."),
        defendant: [.direct("Were your attachments stolen?", "\"Yes, they were. I came to the barn one morning and found the latch loose and the attachments gone from where I keep them.\""),
               .direct("Did you sell any attachments before then?", "\"I sold some old parts to a dealer a month earlier. They were worn-out pieces I no longer used, and they were not the same as the ones on the claim.\""),
               .direct("Why did you file for $14,000?", "\"That is what the stolen attachments are worth, and I listed each one by its serial number. I did not round up or add anything.\""),
               .direct("Why were you in need of money that year?", "\"The harvest failed, and I fell behind on everything. I would never make a false claim because of it, and I would rather lose the farm than lie.\""),
               .direct("How did you cooperate with the adjuster?", "\"I gave every record that I had. I showed the adjuster the dealer's receipt myself, because I had nothing to hide.\""),
               .direct("What will you do now?", "\"I will help sort out which attachments were taken, matching every serial number. I am sorry for the confusion to the adjuster.\""),
               .cross("You sold attachments to a dealer the month before the claim, didn't you?", "\"I sold old parts, not the attachments on the claim. I can see how the receipts look to someone reading them without the whole story.\""),
               .cross("You came before this court in {PRIORDATE} over {PRIOR}, didn't you?", "\"Yes, and I know how that looks beside a claim like this one. I am trying to stay honest, and I have paid for what I did then.\""),
               .cross("The latch on the barn was not pried or cut, was it?", "\"It was loose, and I do not know how it got that way. I did not break it, and I cannot say who did.\""),
               .cross("Some serial numbers on the receipts match your claim, don't they?", "\"A few may, and I do not know how that happened. The dealer's own records show the parts were old, so I believe the numbers got mixed up.\""),
               .cross("You needed money that year, didn't you?", "\"Yes, after a failed harvest. That does not mean I made up a loss, and I would not sell a thing twice.\"")],
        openings: ("{D} reported a barn break-in and filed a $14,000 claim for stolen tractor attachments, but receipts show attachments were sold to a dealer a month earlier. The adjuster found no forced entry, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a list of old parts and a dealer who confirms that the parts sold were not the claimed attachments. A mix-up on paper is not a fraud."),
        closings: ("A claim for items already sold, a barn with no sign of forced entry, and a farmer who needed money after a failed harvest. {D} had been before this court on a similar charge.", "Old parts, new attachments, and a dealer who confirms the difference. The State has not shown that {D} meant to defraud the insurer, only that the paperwork was confused."),
        timeline: [(-30, "{D} sells old tractor parts to an equipment dealer."), (0, "{D} reports a break-in at the barn."), (10, "{D} files a $14,000 claim, and the adjuster finds the sales receipts.")],
        identified: "The adjuster's receipts.",
        mood: .indifferent)

    static let tractorDWIBack = SmallCases.make(
        key: "story.followup.tractorDWIBack",
        category: .traffic,
        headlines: ["Farmer Driving Pickup With Revoked License Stopped at Feed Store", "Tractor DWI Defendant Faces Revoked License Charge"],
        law: "dwlrImpaired",
        spec: "Operated a motor vehicle on a public street while {D.his} license was revoked for an impaired driving conviction, on {DATE}.",
        ages: 48...72,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} drove a farm pickup to a feed store and a deputy checked the plate. {DL}'s license was revoked for impaired driving. {DL} says a farm hand drove and {D.he} only sat in the cab.",
        state: [E(.video, 3, "Store Camera", "{D} steps out of the driver's side."), E(.document, 2, "DMV Record", "{DL}'s license is revoked for impaired driving.")],
        defense: [E(.statement, 1, "Farm Hand", "A farm hand says {D.he} drove and left.")],
        role: "Deputy",
        exam: [.direct("What is your assignment?", "\"I am a sheriff's deputy on patrol. Part of my job is to run license plates and watch for drivers who are not supposed to be on the road.\""),
               .direct("What led you to the feed store that morning?", "\"I was parked across the street and saw a farm pickup pull into the lot. I ran the plate, and it came back to {DL}, whose license is revoked.\""),
               .direct("Who stepped out of the pickup?", "\"{DL}, from the driver's side. {D.He} got out and walked toward the store entrance, and I watched {D.him} do it.\""),
               .direct("What does the store camera show?", "\"It shows {DL} stepping out of the driver's side door and closing it behind {D.him}. You can see {D.him} clearly in the daylight.\""),
               .direct("What does the DMV record show?", "\"{DL}'s license has been revoked for impaired driving, and the revocation was in effect that morning. There is no limited privilege.\""),
               .direct("Did you see anyone else in the pickup?", "\"No. I did not see a passenger or any other person in the cab, and I did not see anyone walk away.\""),
               .direct("What did {DL} say when you spoke with {D.him}?", "\"{D.He} said a farm hand had been driving and that {D.he} had only sat in the cab. {D.He} said the farm hand had left.\""),
               .cross("Did you see the pickup arrive in the lot?", "\"I saw it pull in, but I could not see who was behind the wheel until the door opened.\""),
               .cross("Could a farm hand have walked away before {DL} got out?", "\"It is possible, and the store has a back door. I did not see anyone, but I was watching the front.\""),
               .cross("Did the cashier see a second person?", "\"The cashier says a person left on foot, but I have not been able to speak with that person.\""),
               .cross("Were the keys in {DL}'s pocket?", "\"Yes, they were in {D.his} pocket when I spoke with {D.him}. That is not unusual for a farm owner.\""),
               .cross("You did not see {DL} drive on the road, did you?", "\"No, I saw only the pickup arrive and the driver's door open. I did not follow it from the farm.\"")],
        theory: ("{D} drove a farm pickup to a feed store while {D.his} license was revoked for impaired driving.", "A farm hand drove the pickup, and {D} only sat in the cab."),
        allocution: "\"I did not drive that pickup. My farm hand did, and I only sat in the cab while we went to the feed store. The farm hand has gone to town now. I know my license is revoked, and I'm sorry for the confusion. I'd ask the court to speak to my farm hand.\"",
        truths: ("{DL} had a prior case in this court over a tractor, and the keys were in {D.his} pocket.", "The farm hand drove to the store and left on foot, as a cashier recalls."),
        defendant: [.direct("Did you drive that pickup to the feed store?", "\"No, I did not. My farm hand drove, and I only sat in the cab while we went to the store.\""),
               .direct("Why was a farm hand driving?", "\"My license is revoked, and I knew I could not drive. I asked my farm hand to take me because I needed feed.\""),
               .direct("Where did the farm hand go?", "\"The farm hand drove to the store, parked, and then walked off to buy cigarettes down the road. I did not see where the farm hand went after that.\""),
               .direct("Why did you step out of the driver's side?", "\"I slid across the seat because the passenger door sticks. The driver's door was the easy one to get out of.\""),
               .direct("Where is the farm hand now?", "\"Gone to town, and I do not know where. I would ask the court to speak to the farm hand if the farm hand can be found.\""),
               .direct("What do you regret?", "\"I know my license is revoked, and I am sorry for the confusion. I should have waited until I had a legal ride.\""),
               .cross("The keys were in your pocket, weren't they?", "\"Yes, because the farm hand handed them to me when we parked. I am the owner, and I keep the keys.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know that makes this hard to believe. I was careful this time to let someone else drive.\""),
               .cross("You stepped out of the driver's door in front of a deputy, didn't you?", "\"Yes, I did, because the passenger door sticks. I know it looked like I had been driving.\""),
               .cross("Your license was revoked for impaired driving, wasn't it?", "\"Yes, and I have not driven since. That is why I had my farm hand take me.\""),
               .cross("You cannot name the farm hand or say where to find the farm hand, can you?", "\"I know a first name and a town, and I have given both to the deputy. I have not been able to reach the farm hand since.\"")],
        openings: ("A deputy ran the plate on a farm pickup at a feed store, saw {D} step out of the driver's side, and found that {D}'s license was revoked for impaired driving. The store camera shows it, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a farm hand who drove the pickup and left on foot, as a cashier recalls. A person who steps out of a stuck door is not proof of who drove."),
        closings: ("The store video shows {D} stepping out of the driver's side, the keys were in {D}'s pocket, and the revocation was in effect. {D} had been before this court over impaired driving.", "A farm hand at the wheel, a cashier who saw someone walk off, and a stuck passenger door. The State has not shown beyond a reasonable doubt that {D} drove that pickup."),
        timeline: [(0, "Morning: {D} and a farm hand leave the farm in a pickup and drive to a feed store."), (0, "A deputy runs the plate and the store camera records {D} stepping out of the driver's side."), (0, "A cashier recalls someone walking away on foot."), (1, "{D} is charged with driving while license revoked for impaired driving.")],
        identified: "The store camera.",
        mood: .indifferent)

}
